// general routine naming conventions:
//  gXxxx: global routines, cross platform
//  tg_gtk_xxx: local, gtk only
//  tg_WinAPI_xxx: local, WinAPI only
//  tg_xxx: local, cross_platform

// types:
//  gdx: an index to the internal tables, such as $ctrl_handles[].
//  rtn: NULL or the routine identifier (aka integer index into symtab) of a suitable handler routine.
/*without pushtrace*/
/*global*/ function gdx(/*object*/ hdx) {
    let /*integer*/ l = (($bInit) ? length($ctrl_types) : 0);
    if (sequence(hdx)) {
        if (string(hdx)) { return false; }
        for (let h$idx = 1, h$lim = length(hdx); h$idx <= h$lim; h$idx += 1) { let h = $subse(hdx,h$idx);
            if (!((integer(h) && h>=0) && h<=l)) { return false; }
        }
        return true;
    }
    return (integer(hdx) && compare(hdx,0)>=0) && compare(hdx,l)<=0;
} gdx.$sig="TO";

/*local*/ function gdx_name(/*integer*/ id) {
    return ((id<=0) ? ((id===0) ? `NULL` : ((odd(id)) ? `Image` : `Pixbuf`)) : $subse($ctrl_names,$subse($ctrl_types,id)));
} gdx_name.$sig="FI";
// nFrames is used heavily on routines throughout theGUI such as the following,
// with the aim of making gButton("JUNK=1"), gSetAttribute(btn,"JUNK",1), and
// gSetAttributes(btn,"JUNK=1") report errors in applicaton code rather than 
// the code of theGUI itself. Should you need to see the full call stack, just
// comment out that last parameter. Note that several/most tg_set_xxx_attribute
// routines have nFrames+2 because there is an implicit call_func() from the end
// of gSetAttribute(), which obviously also deserves to be skipped.

/*local*/ function $tg_bad_attr(/*gdx*/ id, /*string*/ name, /*integer*/ nFrames=1) {
    crash(`gGetAttribute(%s,%s)`,["sequence",gdx_name(id),name],nFrames+1);
} $tg_bad_attr.$sig="POSI,1";
