/*local*/ function $tg_WinAPI_get_wm_name(/*integer*/ msg) { // diag aid (WinAPI only)
    let /*integer*/ k = find(msg,$WM_MSGS);
    return ((k) ? $subse($WM_NAMES,k) : msg);
} $tg_WinAPI_get_wm_name.$sig="FI";

/*local*/ function $tg_WinAPI_wm_ignorable(/*integer*/ msg) {
//  if msg>=$WM_USER then return true end if
    return compare(msg,$WM_USER)>=0 || find(msg,["sequence",1,3,6,10,12,13,14,19,20,24,28,30,31,33,48,70,71,77,83,123,127,129,130,131,132,133,134,136,144,147,148,160,161,162,163,164,165,174,273,278,279,287,289,293,296,528,529,530,533,536,537,562,641,642,674,799]);
} $tg_WinAPI_wm_ignorable.$sig="FI";

