/*local*/ const $CMAX = 1000;

/*local*/ let /*object*/ $c_log = NULL;

/*local*/ let /*integer*/ $c_next;
// DEBUG_FLAGS:
// ===========
//  Specifically what we're getting from and sending to the $backend GUI (ie GTK or WinAPI).
//  A message such as c_func($xSetWindowPos[4983],...) means `as called from on line 4983`.
//   (note that said line numbers are hard/hand-coded and will gradually become outdated.)
//  Every (trapped) name must have $DF_FLAGS set (non-zero), can be mixed as heart desires.
//  Note this is just an attempt to retain effort from prior debug sessions, not a panacea.
//  Should help when debugging fairly similar things - but hopefully not exactly the same.
//  This is squarely aimed at the 8 interacting tg_lm_xxx() routines, initially anyway,
//  if you can debug something in the normal way my advice would be to do just that.
/*local*/ const 
                $DF_NONE = 0x0, 
                $DF_SIZE_API = 0x1, 
                $DF_SET_XY = 0x2, 
                $DF_SET_WH = 0x4, 
//X DF_SET_NAT  := 0x08,
//  $DF_SET_NORM := 0x10,
                $DF_SET_NORM = 0x8,  // setting $ctrl_size[id][$SZ_NORMAL_W|$SZ_NORMAL_H]
                $DF_SET_USER = 0x10,  // setting $ctrl_size[id][$SZ_USER_W|$SZ_USER_H]
                $DF_SB_INFO = 0x100,  // setting $ctrl_sbinfo[id]
//  DF_SBINFO_X := 0x01x0,  -- setting $ctrl_sbinfo[id][X] --??? (maybe, #110..#180?)
                $DF_FLAGS = new_dict(); // key is string, data is (int) DEBUG_FLAGS
//  $DF_ACTIVE = $DF_SIZE_API,    -- to/from $backend API
//  $DF_ACTIVE = $DF_SIZE_API+$DF_SET_WH,
//  $DF_ACTIVE = $DF_SIZE_API+$DF_SET_WH+$DF_SET_NORM,
//  $DF_ACTIVE = $DF_SET_XY,      -- setting $ctrl_size[id][$SZ_X|$SZ_Y]
//  $DF_ACTIVE = $DF_SET_WH,      -- setting $ctrl_size[id][$SZ_W|$SZ_H]
//  $DF_ACTIVE = $DF_SET_XY+$DF_SET_WH,
//X $DF_ACTIVE = DF_SET_NAT,     -- setting $ctrl_size[id][SZ_NATURAL_W|SZ_NATURAL_H]
//  $DF_ACTIVE = $DF_SET_NORM,    
let /*integer*/ $DF_ACTIVE = $DF_NONE; // show nowt, set by gSetGlobal(`DIAGNOSTICS`,`...`)
let /*bool*/ $dump_ctrls_on_resize = false; // set by gSetGlobal(`DIAGNOSTICS`,`DUMPONRESIZE`)
setd(`SetWindowPos`,$DF_SIZE_API,$DF_FLAGS);
setd(`gtk_window_resize`,$DF_SIZE_API,$DF_FLAGS);
setd(`gtk_window_set_default_size`,$DF_SIZE_API,$DF_FLAGS);
setd(`gtk_widget_size_allocate`,$DF_SIZE_API,$DF_FLAGS);
setd(`ctrl_sizeXY`,$DF_SET_XY,$DF_FLAGS);
setd(`ctrl_sizeWH`,$DF_SET_WH,$DF_FLAGS);
//setd(`ctrl_sizeNAT`,DF_SET_NAT,$DF_FLAGS) [DEAD]
setd(`ctrl_sizeNORM`,$DF_SET_NORM,$DF_FLAGS);
setd(`ctrl_sizeUSER`,$DF_SET_USER,$DF_FLAGS);
setd(`ctrl_sbinfo`,$DF_SB_INFO,$DF_FLAGS);
let /*bool*/ $nodump = false; // (unit tests i/p) mainly don't call $tg_lm_dump_ctrls(), but several other things too

/*local*/ function $g_log(/*string*/ fp, name, /*object*/ qual, /*sequence*/ args, /*bool*/ bShowRes=false, /*object*/ res=0) {
    // fp is one of `c_func`, `c_proc`, `callback`, `call`, or `set`, etc.
    // name is eg `xSetWindowPos` or `??` (both being $backend-specific) or `ctrl_sizeWH`.
    if ((equal($DF_ACTIVE,$DF_NONE)) || $nodump) { return; }
    let /*integer*/ nf = getdd(name,-1,$DF_FLAGS), dotypes = 0;
    assert(nf!==-1,$conCat(name, ` not set in DF_FLAGS`));
    if (equal(and_bits(nf,$DF_ACTIVE),0)) { return; }
    if (equal($c_log,NULL)) {
        $c_log = repeat(0,$CMAX);
        $c_next = 1;
    }
    $c_log = $repe($c_log,$c_next,["sequence",fp,name,qual,args]);
    $c_next = remainder($c_next,$CMAX)+1;
    $c_log = $repe($c_log,$c_next,0);
            crash(`JS`);
    for (let i = 1, h$lim = dotypes; i <= h$lim; i += 1) { let h = $subse(args,i);
        if (h===0) {
            args = $repe(args,i,`NULL`);
        } else {
            h = $tg_getID(h);
            args = $repe(args,i,["sequence",h,gdx_name(h)]);
        }
    }
    if (!equal(qual,0)) {
        if (integer(qual)) { qual = sprintf(`%d`,qual);
        } else if (!string(qual)) { qual = sprintf(`%s(%d)`,qual);
        }
        name = sprintf(`%s[%s]`,["sequence",name,qual]);
    }
    if (bShowRes) {
        printf(1,"%s(%s,%v) ==> %v\n",["sequence",fp,name,args,res]);
    } else {
        printf(1,"%s(%s,%v)\n",["sequence",fp,name,args]);
    }
} $g_log.$sig="PSSOPIO,1";
//
// **NB** It would be quite wrong to blanket-call this, for instance $tg_getID would crash,
//        and getting info back from WinAPI/GTK is generally of little interest. Instead,
//        what is of real interest are calls we make that supply wrong info to WinAPI/GTK.
//         (actually, that's more like wrong info in ctrl_sizes[], in more recent times)
//        Each entry point we decide to monitor, one at a time, probably requires the same
//        sort of tweaks as shown for $xGetWindowRect above. Actually maybe there is a case
//        for logging everything, so you don't have to pester an end user, but I do rather
//        doubt that will (ever) be significant/useful/critical for theGUI, in here almost
//        everything will be solved by me anyway. Filtering options are unlimited: on each
//        call, in $g_func/proc, or during a post-mortem on an as yet unwritten g_dump_all.
//
/*local*/ function $g_func(/*integer*/ rid, /*sequence*/ args, /*object*/ qual=0) {
    let /*atom*/ res = c_func(rid,args);
    $g_log(`c_func`,c_name(rid),qual,args,true,res);
    return res;
} $g_func.$sig="FIPO,1";

/*local*/ function $g_proc(/*integer*/ rid, /*sequence*/ args, /*object*/ qual=0) {
    c_proc(rid,args);
    $g_log(`c_proc`,c_name(rid),qual,args);
} $g_proc.$sig="PIPO,1";
// these three specifically avoid the need to declare/test bOK/res:
/*local*/ function $g_funk(/*integer*/ rid, /*sequence*/ args, /*object*/ qual=0) {
    let /*bool*/ bOK = c_func(rid,args);
    $g_log(`c_func`,c_name(rid),qual,args,true,bOK);
    assert(bOK);
} $g_funk.$sig="PIPO,1";

/*local*/ function $c_funk(/*integer*/ rid, /*sequence*/ args) {
    let /*bool*/ bOK = c_func(rid,args);
    assert(bOK);
} $c_funk.$sig="PIP";

/*local*/ function $c_funz(/*integer*/ rid, /*sequence*/ args) {
    let /*atom*/ res = c_func(rid,args);
    assert(res!==0);
} $c_funz.$sig="PIP";

/*local*/ let /*sequence*/ $gtk_version;

/*local*/ function $tg_to_bool(/*object*/ v, nFrames=1) {
    // convert `YES`/`NO`/etc to true/false (as a common requirement)
    if (string(v)) {
        let /*string*/ uv = upper(v);
        if (find(uv,["sequence",`YES`,`ON`,`1`,`TRUE`])) { v = true;
        } else if (find(uv,["sequence",`NO`,`OFF`,`0`,`FALSE`])) { v = false;
        } else {
            crash(`unrecognised("%s")`,["sequence",v],nFrames+1);
        }
    } else {
        assert((equal(v,true)) || (equal(v,false)),"t/f?",["sequence"],nFrames+1);
    }
    return v;
} $tg_to_bool.$sig="FOO,3";

/*local*/ function $tg_to_int(/*object*/ v) {
    // convert eg `20` to 20, but v may already be integer
    if (string(v)) {
        v = to_number(v);
    }
    assert(integer(v));
    return v;
} $tg_to_int.$sig="FO";

/*local*/ function $tg_intint(/*string*/ val, name, /*integer*/ nFrames) {
    //
    // convert eg `225x75` to {225,75}, and in fact 
    //            `50x10x20x30` to {50,10,20,30},
    //            `1`->{1}, and `1x2x3`->{1,2,3}.
    // likewise eg `{225,75}` -> {225,75}, etc.
    //
    let /*sequence*/ res;
    if (equal($subse(val,1),0X7B)) {
        assert(equal($subse(val,-1),0X7D));
        res = split($subss(val,2,-2),0X2C);
    } else {
        res = split(val,0X78,false); // (eg `x50` -> {"","50})
    }
    for (let i = 1, ri$lim = length(res); i <= ri$lim; i += 1) { let ri = $subse(res,i);
        assert((ri==="") || is_integer(ri),$conCat($conCat($conCat("invalid ", name), ":"), val),nFrames+1);
        res = $repe(res,i,to_integer(ri));
    }
    return res;
} $tg_intint.$sig="FSSI";

