function $tg_set_font(/*gdx*/ id, /*atom*/ handle, /*string*/ v, /*atom*/ angle=0) {
    // Either the gdx or handle should be null:
    // When gdx!=0 this is really setting up the cache for inheritance,
    // else handle is a pango layout or a compatible DC into which the
    // target image has already been (/perhaps soon will be) selected.

//DEV togo: (replace with $cached_font_names[inherited($ctrl_font[id])]...?
    if (id) {
        $ctrl_fonts = $repe($ctrl_fonts,id,v);
    }
    let /*atom*/ fontdesc;
    let /*integer*/ comma = find(0X2C,v), 
                    fontsize = 0, k;
    let /*string*/ face = $subss(v,1,comma-1), 
                   facerest = ``;
    let /*sequence*/ styles = ["sequence"], fsf;
    if (comma) {
        styles = split_any($subss(v,comma+1,-1),` ,`);
        fontsize = to_integer($subse(styles,-1));
        if (fontsize) { styles = $subss(styles,1,-1-1); }
        for (let i = 1, s$lim = length(styles); i <= s$lim; i += 1) { let s = $subse(styles,i);
            s = proper(s);
            if (!equal(s,`Normal`)) {
                facerest = $conCat(facerest, $conCat(` `, s), false);
            }
            styles = $repe(styles,i,s);
        }
    }
    if (fontsize<0) {
        facerest = $conCat(facerest, sprintf(` %dpx`,-fontsize), false);
    } else if (fontsize) {
        facerest = $conCat(facerest, sprintf(` %d`,fontsize), false);
    }
            crash(`JS`);
} $tg_set_font.$sig="PONSN,1";

/*local*/ function $tg_get_inherited_flag(/*integer*/ id, flag) {
    while (true) {
        if (and_bits($subse($ctrl_flags,id),flag)) {
            return false;
        }
        id = $subse($ctrl_parent,id);
        if (id===0) {
            break;
        }
    }
    return true;
} $tg_get_inherited_flag.$sig="FII";

