/*global*/ function gGetInt(/*$gcx*/ id, /*string*/ name, /*integer*/ nFrames=1) {
    // not suitable for: CLASSNAME,...
    if (id>0) {
        let /*integer*/ ct = $subse($ctrl_types,id);
        if (equal(name,`EXPAND`)) {
            return and_bits($subse($ctrl_flags,id),$CF_EXPAND);
        } else if (equal(name,`SPACE`)) {
            assert(equal(ct,$BOX));
            let /*integer*/ h = $subse($subse($ctrl_xtra,id),$CX_BOX_SPACE_H), 
                            v = $subse($subse($ctrl_xtra,id),$CX_BOX_SPACE_V);
            return ((h===v) ? h : ["sequence",h,v]);
//DEV untested:
        } else if ((equal(name,`SELMODE`)) || (equal(name,`CELLMODE`))) {
            assert(equal($subse($ctrl_types,id),$TABLE));
            return $subse($subse($ctrl_xtra,id),$CXTBL_SELMODE);
        } else if ((equal(name,`ORIENTATION`)) && (equal(ct,$BOX))) {
            let /*bool*/ bHoriz = equal(and_bits($subse($ctrl_flags,id),$CF_VERTICAL),0);
            return bHoriz;
        }
    }
//  object ores = gGetAttribute(id,name,dflt,nFrames+1)
    let /*object*/ ores = gGetAttribute(id,name,nFrames+1);
    let /*integer*/ res = ((string(ores)) ? to_number(ores) : ores);
    return res;
} gGetInt.$sig="FISI,1";
