/*global*/ function rgba(/*object*/ red, /*atom*/ green=-1, blue=-1, alpha=0) {
    if (sequence(red)) {
        assert(((green===-1) && (blue===-1)) && (alpha===0)); // (check exactly one arg)
        // not only would (`red`) or (`#FF0000`) be quite wrong, the
        //  following also acts as a JavaScript compatibility check,
        //  as in pre-emptively crashing on desktop/Phix way b4 p2js.
        assert(!string(red));
        let /*integer*/ lr = length(red);
        if (lr===3) {
            [,red,green,blue] = red;
        } else if (lr===4) {
            [,red,green,blue,alpha] = red;
        } else {
            crash(`red not length 3|4)`,{},2);
        }
//      assert(atom(red)) -- (will be caught by and_bits anyway)
    }
    // guard against rgba(atom) and rgba(atom,atom) calls:
    assert((green!==-1) && (blue!==-1));
    let /*atom*/ colour = 
                          ((and_bits(alpha,0xFF)*0x1000000+and_bits(red,0xFF)*0x10000)+and_bits(green,0xFF)*0x100)+and_bits(blue,0xFF);
    return colour;
} rgba.$sig="FONNN,1";

/*global*/ function $hsv_to_rgba(/*atom*/ h, s, v, a=0) {
    let /*integer*/ i = floor(h*6);
    let /*atom*/ f = h*6-i;
    let /*integer*/ p = and_bits((v*(1-s))*0xFF,0xFF), 
                    q = and_bits((v*(1-s*f))*0xFF,0xFF), 
                    t = and_bits((v*(1-s*(1-f)))*0xFF,0xFF), 
                    r, g, b;
    v = and_bits(v*0xFF,0xFF);
//  a = #FF-and_bits(a*#FF,#FF)
    a = and_bits(a*0xFF,0xFF);
    switch (i) {
        case 0: case 6: [,r,g,b] = ["sequence",v,t,p];
            break;
        case 1: [,r,g,b] = ["sequence",q,v,p];
            break;
        case 2: [,r,g,b] = ["sequence",p,v,t];
            break;
        case 3: [,r,g,b] = ["sequence",p,q,v];
            break;
        case 4: [,r,g,b] = ["sequence",t,p,v];
            break;
        case 5: [,r,g,b] = ["sequence",v,p,q];
    }
    return rgba(r,g,b,a);
} $hsv_to_rgba.$sig="FNNNN,7";

/*global*/ function to_rgb(/*atom*/ colour) {
    let /*integer*/ red = and_bits(colour,0xFF0000)/0x10000, 
                    green = and_bits(colour,0xFF00)/0x100, 
                    blue = and_bits(colour,0xFF);
    return ["sequence",red,green,blue];
} to_rgb.$sig="FN";

/*global*/ function to_rgba(/*atom*/ colour) {
    let /*integer*/ red = and_bits(colour,0xFF0000)/0x10000, 
                    green = and_bits(colour,0xFF00)/0x100, 
                    blue = and_bits(colour,0xFF), 
                    alpha = and_bits(colour,0xFF000000)/0x1000000;
//  return {red,green,blue,#FF-alpha}
    return ["sequence",red,green,blue,alpha];
} to_rgba.$sig="FN";

/*local*/ function $tg_WinAPI_rgb_to_bgr(/*atom*/ colour) {
    // (aside: in case it helps, this is bi-directional)
    let /*atom*/ r = and_bits(colour,0xFF0000)/0x10000, 
                 b = and_bits(colour,0xFF)*0x10000, 
                 c = (and_bits(colour,0xFF00FF00)+r)+b;
    return c;
} $tg_WinAPI_rgb_to_bgr.$sig="FN";
/*
My rgba to bgra colour conversion routine appears to be dog-slow.
What x86/X64 assembly would I need to convert say #AABBCCDD in eax/rax to #55DDCCBB?

OK, the first version looks good, although actually 6 instructions, but the slightly
tighter one is also 6 instructions, three bytes longer, and will produce #55CCBBAA, won't it?

OK, I may as well explain what the real situation is here (bit of old-fashioned rubber duck debugging, if you will).
Obviously there is a fair bit of code around this, but it's identical for gtk/win32, the latter inner bit is just:
            poke4(pMem,colour)
which manages a quite respectable 200,000/s, whereas the gtk side has this inner bit
            poke4(pMem,$tg_GTK_rgba_to_bgra(colour))
along with
            function $tg_GTK_rgba_to_bgra(atom colour)
                atom a = #FF000000-and_bits(colour,#FF000000),
                     r = and_bits(colour,#00FF0000)/#10000,
                     b = and_bits(colour,#000000FF)*#10000,
                     c = and_bits(colour,#0000FF00)+a+r+b
                return c
            end function
which crawls along at a paltry 60/s, quite astonishingly slower by worse than 3,000 times!

colour = xor_bits(colour,#FF000000)
       + and_bits(colour,#0000FF00)
       + (and_bits(colour,#00FF0000) >> 16)
       + (and_bits(colour,#000000FF) << 16)
poke4(pMem,c)

mov     ecx, eax
xor     ecx, 0FF000000h ; invert alpha
bswap   eax
shr     eax, 8
and     ecx, 0FF000000h
or      eax, ecx

nah, this is better/cooler!

bswap   eax
ror     eax,8
xor     eax,0FF000000h

AABBCCDD   original
DDCCBBAA   bswap
AADDCCBB   ror 8
55DDCCBB   xor FF000000
*/

/*local*/ function $tg_GTK_rgba_to_bgra(/*atom*/ colour) {
    // (aside: in case it helps, this is bi-directional)
    let /*atom*/ a = 0xFF000000-and_bitsu(colour,0xFF000000), 
                 r = and_bits(colour,0xFF0000)/0x10000, 
                 b = and_bits(colour,0xFF)*0x10000, 
                 c = ((and_bits(colour,0xFF00)+a)+r)+b;
    return c;
} $tg_GTK_rgba_to_bgra.$sig="FN";

