/*global*/ function gRedraw(/*gdx*/ id, /*bool*/ bNow=false) {
    // Aside: the invalidate rect seems to be enough to trigger tg_lm_ stuff...
    if (and_bits($subse($ctrl_flags,id),$CF_SPLIT)) {
        $tg_resize_for_splitter(id);
    }
    let /*gdx*/ dlg = gGetDialog(id);
    if (dlg) {
        if ($bDumpOnRedraw) {
            $tg_lm_dump_ctrls(source_line(4707),`gRedraw`);
        }
        let /*atom*/ handle = $subse($ctrl_handles,dlg);
        if ($backend===TG_GTK) {
            let /*atom*/ window = c_func($x_gtk_widget_get_window,["sequence",handle]);
            if (window) {
                let /*atom*/ pTitle = c_func($x_gtk_window_get_title,["sequence",handle]);
                if (pTitle) {
                    c_proc($x_gtk_window_set_title,["sequence",handle,pTitle]);
                }
                c_proc($x_gdk_window_invalidate_rect,["sequence",window,NULL,true]);
            }
            c_proc($x_gtk_widget_queue_draw,["sequence",handle]);
            // Aside: I'm sure this was once needed for gProgress.exw,
            //        but now it seems to make no difference... (in a good way)
            // hence I've taken bNow out of the docs...
            if (window && bNow) {
                c_proc($x_gdk_window_process_updates,["sequence",window,true]);
            }
        } else if ($backend===TG_WINAPI) {
            $c_funk($xInvalidateRect,["sequence",handle,NULL,false]);
        } else if ($backend===TG_JS) {
                crash(`JS`);
        } else {
            crash("9/0"); // (unknown $backend)
        }
    } else {
        // note this is for popups; for (only) the menubar just gRedraw(menu)
        if ($backend===TG_GTK) {
            let /*atom*/ hPopup = $subse($subse($ctrl_hdc,id),2);
            c_proc($x_gtk_widget_queue_draw,["sequence",hPopup]);
        } else if ($backend===TG_WINAPI) {
            let /*atom*/ hWnd = $subse($subse($ctrl_hdc,id),1);
            $c_funk($xInvalidateRect,["sequence",hWnd,NULL,false]);
        } else if ($backend===TG_JS) {
                crash(`JS`);
        } else {
            crash("9/0"); // unknown $backend
        }
    }
} gRedraw.$sig="POI,1";

