    $ctrl_xtra = $repe($ctrl_xtra,$MX_WIDTH,width,["sequence",mdx,$CX_MEXTRA,menu]);
    $ctrl_xtra = $repe($ctrl_xtra,$MX_HEIGHT,height,["sequence",mdx,$CX_MEXTRA,menu]);
