/*local*/ function $tg_next_enabled(/*gdx*/ menu, /*sequence*/ items, /*integer*/ i, d) {
    let /*integer*/ l = length(items);
    for (let k=1, k$lim=l; k<=k$lim; k+=1) { // (max once round/check nowt twice)
        i += d;
        if (i<1) {
            i = l;
        } else if (i>l) {
            i = 1;
        }
        let /*bool*/ enabled = $subse($subse(items,i),$MX_ENABLED);
        let /*integer*/ submenu = $subse($subse(items,i),$MX_SUBMENU);
        if (submenu && (equal(length($subse($subse($subse($subse($ctrl_xtra,menu),$CX_MENUS),submenu),$MX_ITEMS)),0))) {
            enabled = false;
        }
        if (enabled) {
            return i;
        }
    }
    return 0;
} $tg_next_enabled.$sig="FOPII";
function $tg_process_menu_keydown(/*gdx*/ menu, /*integer*/ mdx, key) {
    // invoked from main_key_cb rather than menu_key_cb (GTK)
    // invoked from WndProc rather than PopMenuWndProc (WinAPI)
    let /*object*/ cxm = $subse($ctrl_xtra,menu), 
                   mxtra = $subse($subse(cxm,$CX_MEXTRA),mdx);
    let /*sequence*/ items = $subse($subse($subse(cxm,$CX_MENUS),mdx),$MX_ITEMS);
    let /*integer*/ sel_item = $subse(mxtra,$MX_SEL), 
                    parent = $subse($subse($subse(cxm,$CX_MENUS),mdx),$MX_PARENT);
    let /*atom*/ hWnd = $subse(mxtra,$MX_POPUP), 
                 hMenu = $subse(mxtra,$MX_WIDGET);
    cxm = 0; // (kill refcount)
    mxtra = 0; // (kill refcount)
    if ((key===VK_UP) || (key===VK_DOWN)) {
        let /*integer*/ d = ((key===VK_UP) ? -1 : +1);
        sel_item = $tg_next_enabled(menu,items,sel_item,d);
        if (sel_item<0) { crash("9/0"); }
        $ctrl_xtra = $repe($ctrl_xtra,$MX_SEL,sel_item,["sequence",mdx,$CX_MEXTRA,menu]);
        $ctrl_xtra = $repe($ctrl_xtra,$MX_HOT,sel_item,["sequence",mdx,$CX_MEXTRA,menu]);
        $ctrl_xtra = $repe($ctrl_xtra,$MX_KEYMODE,true,["sequence",mdx,$CX_MEXTRA,menu]);
        $tg_menu_redraw(menu,mdx);
        $tg_call_menu_handler(menu,mdx,sel_item,true,false);
    } else if (((key===VK_CR) && sel_item>0) && (equal($subse($subse(items,sel_item),$MX_SUBMENU),0))) {
        $tg_call_menu_handler(menu,mdx,sel_item,false,true);
//      return true -- GTK?
    } else if ((key===VK_RIGHT) || (key===VK_CR)) {
        if (sel_item>0) {
            let /*bool*/ enabled = $subse($subse(items,sel_item),$MX_ENABLED);
            let /*integer*/ submenu = $subse($subse(items,sel_item),$MX_SUBMENU);
            if (submenu && (equal(length($subse($subse($subse($subse($ctrl_xtra,menu),$CX_MENUS),submenu),$MX_ITEMS)),0))) {
                enabled = false;
            }
            if (submenu && enabled) {
                $ctrl_xtra = $repe($ctrl_xtra,$MX_KEYMODE,true,["sequence",mdx,$CX_MEXTRA,menu]);
                $ctrl_xtra = $repe($ctrl_xtra,$MX_HOT,0,["sequence",mdx,$CX_MEXTRA,menu]);
                $tg_menu_redraw(menu,mdx);
                $tg_open_child_menu(menu,submenu,mdx,sel_item);
                // auto-select top item:
                items = $subse($subse($subse($subse($ctrl_xtra,menu),$CX_MENUS),submenu),$MX_ITEMS);
                let /*integer*/ first = $tg_next_enabled(menu,items,0,+1);
                $ctrl_xtra = $repe($ctrl_xtra,$MX_KEYMODE,true,["sequence",submenu,$CX_MEXTRA,menu]);
                $ctrl_xtra = $repe($ctrl_xtra,$MX_SEL,first,["sequence",submenu,$CX_MEXTRA,menu]);
                $ctrl_xtra = $repe($ctrl_xtra,$MX_HOT,first,["sequence",submenu,$CX_MEXTRA,menu]);
                $tg_call_menu_handler(menu,submenu,first,true,false);
            }
        }
    } else if (key===VK_LEFT) {
        if (parent>0) {
            $tg_hide_one_menu(menu,mdx,false);
            let /*integer*/ psel = $subse($subse($subse($subse($ctrl_xtra,menu),$CX_MEXTRA),parent),$MX_SEL);
            $ctrl_xtra = $repe($ctrl_xtra,$MX_HOT,psel,["sequence",parent,$CX_MEXTRA,menu]);
            $ctrl_xtra = $repe($ctrl_xtra,$MX_KEYMODE,true,["sequence",parent,$CX_MEXTRA,menu]);
            $tg_menu_redraw(menu,parent);
            $tg_call_menu_handler(menu,parent,psel,true,false);
        }
    }
    return 0;
} $tg_process_menu_keydown.$sig="FOII";
