/*local*/ function $PopMenuWndProc_cb(/*atom*/ hWnd, msg, wParam, lParam) {
    let /*integer*/ [,menu,mdx] = $tg_find_menu(hWnd,$MX_POPUP);
    if (mdx) {  // ignore eg WM_CREATE which arrives before any menus[mdx] gets the hWnd
        switch (msg) {
            case $WM_ACTIVATE:  // (not strictly needed, but safer)
                if (equal($LOWORD(wParam),$WA_INACTIVE)) {
                    $tg_hide_one_menu(menu,mdx,false);
                }
                return 0;
                break;
            case $WM_SETFOCUS:  // (not strictly needed, but safer)
                return 0;
                break;
            case $WM_NCACTIVATE:  // (not strictly needed, but safer)
                return true;
                break;
            case $WM_MOUSEACTIVATE:
                return $MA_NOACTIVATE;
                break;
            case $WM_MOUSEMOVE:
                let /*integer*/ x = and_bits(lParam,0xFFFF), 
                                y = floor(lParam/0x10000);
                $tg_menu_mousemove(menu,mdx,x,y);
//              return 0 -- (no help with the menu thing)
//              return 1 -- ""
                break;
            case $WM_MOUSELEAVE:
                $tg_menu_leave(menu,mdx);
                return 0;
                break;
            case $WM_LBUTTONDOWN:
                $tg_menu_leftclick(menu,mdx);
                return 0;
                break;
            case $WM_PAINT:
                $tg_draw_menu(menu,mdx);
                let /*sequence*/ mxtra = $subse($subse($subse($ctrl_xtra,menu),$CX_MEXTRA),mdx);
                let /*gdm*/ img = $subse(mxtra,$MX_TGTIMG);
                let /*integer*/ imdx = (-img+1)/2, 
                                w = $subse(mxtra,$MX_WIDTH), 
                                h = $subse(mxtra,$MX_HEIGHT);
                let /*$nnatom*/ dstDC = c_func($xBeginPaint,["sequence",hWnd,$pPAINTSTRUCT]), 
                               srcDC = $tg_WinAPI_GetSrcDC(), 
                               src_img = $subse($subse($gimages,imdx),$TG_IMG_HANDLE), 
                               prevBM = c_func($xSelectObject,["sequence",srcDC,src_img]);
                $c_funk($xBitBlt,["sequence",dstDC,0,0,w,h,srcDC,0,0,$SRCCOPY]);
                prevBM = c_func($xSelectObject,["sequence",srcDC,prevBM]);
                c_proc($xEndPaint,["sequence",hWnd,$pPAINTSTRUCT]);
                return 0;
                break;
            case $WM_KEYDOWN:
//              -- directly routed as if via this by WndProc:
//              return $tg_process_menu_keydown(menu,mdx,wParam)
                return 0; // (extra paranoia, let WndProc always do it)
        }
    }
    return c_func($xDefWindowProc,["sequence",hWnd,msg,wParam,lParam]);
} $PopMenuWndProc_cb.$sig="FNNNN";
