/*local*/ function $tg_scrollbar_click(/*gdx*/ canvas, /*sequence*/ status, /*integer*/ x, y) {
    let /*object*/ sbinfo = $subse($ctrl_sbinfo,canvas);
    if (!sequence(sbinfo)) { return false; }
    sbinfo = NULL;
    let /*string*/ clikmon = $tg_get_mouse_on_scrollbar(canvas,x,y);
    $ctrl_sbinfo = $repe($ctrl_sbinfo,$SB_CKMON,clikmon,["sequence",canvas]);
    $ctrl_sbinfo = $repe($ctrl_sbinfo,$SB_CLIKX,x,["sequence",canvas]);
    $ctrl_sbinfo = $repe($ctrl_sbinfo,$SB_CLIKY,y,["sequence",canvas]);
    let /*bool*/ dragg = !equal($subse(status,2),0X52), 
                 wasdrag = $subse($subse($ctrl_sbinfo,canvas),$SB_DRAGG);
    $ctrl_sbinfo = $repe($ctrl_sbinfo,$SB_DRAGG,dragg,["sequence",canvas]);
    let /*gdx*/ timer = $subse($subse($ctrl_sbinfo,canvas),$SB_TIMER);
    if (dragg) {
        if (!find(clikmon,["sequence",``,`VT`,`HT`])) {
            $tg_scrollbar_timer_action(canvas);
            if (!timer) {
                timer = gTimer($tg_scrollbar_timer_cb,500,true,canvas);
                $ctrl_sbinfo = $repe($ctrl_sbinfo,$SB_TIMER,timer,["sequence",canvas]);
            } else {
                gSetAttribute(timer,`TIME`,500);
                gSetAttribute(timer,`RUN`,true);
            }
            $ctrl_sbinfo = $repe($ctrl_sbinfo,$SB_DRAGG,false,["sequence",canvas]);
            dragg = false;
        }
    } else {
        if (timer) { gSetAttribute(timer,`RUN`,false); }
    }
    $g_log(`set`,`ctrl_sbinfo`,source_line(8455),deep_copy($subse($ctrl_sbinfo,canvas)));
    if (dragg!==wasdrag) { gRedraw(canvas); }
    return !equal(clikmon,``);
} $tg_scrollbar_click.$sig="FOPII";

/*local*/ function $tg_click_handler(/*gdx*/ dlg, /*sequence*/ status, /*integer*/ x, y) {
    // GTK and WinAPI part
    let /*gdx*/ id = dlg, menu = NULL;
    if (equal($subse($ctrl_types,dlg),$DIALOG)) {
        id = $hit_test(dlg,x,y);
        menu = $subse($subse($ctrl_xtra,dlg),$DX_ACTIVEPOP);
        gSetFocus(id); // 10/11/25, for hCalendar
    }
    let /*integer*/ clickhandler = gGetHandler(id,`CLICK`), 
                    ct = $subse($ctrl_types,id);
    if (((!equal(ct,$MENU)) && menu) && (equal($subse(status,2),0X53))) {
        crash("tg_hide(menu)"); // yet to see this happen...
    }
    if (and_bits($subse($ctrl_flags,id),$CF_CANVAS)) {
        if ($tg_scrollbar_click(id,status,x,y)) {
            clickhandler = NULL;
        }
    }
    if (clickhandler) {
        let /*string*/ sig = $tg_get_sig(clickhandler);
        if ((!equal(ct,$DIALOG)) && compare(length(sig),3)>0) {
            x -= $subse($subse($ctrl_size,id),$SZ_X);
            y -= $subse($subse($ctrl_size,id),$SZ_Y);
        }
        let /*object*/ res = TG_IGNORE;
        if (equal(sig,`FOPII`)) {
            res = clickhandler(id,status,x,y);
        } else if (equal(sig,`POPII`)) {
            clickhandler(id,status,x,y);
        } else if (equal(sig,`FOP`)) {
            res = clickhandler(id,status);
        } else if (equal(sig,`POP`)) {
            clickhandler(id,status);
        } else {
            crash("9/0"); // unknown sig...
        }
        if (string(res)) {
            if (equal(res,`CAPTURE`)) {
                if ($backend===TG_GTK) {
                    let /*atom*/ widget = $subse($ctrl_handles,dlg);
                    $c_funk($x_gtk_widget_grab_focus,["sequence",widget]);
                    c_proc($x_gtk_grab_add,["sequence",widget]);
                } else if ($backend===TG_WINAPI) {
                    c_proc($xSetCapture,["sequence",$subse($ctrl_handles,dlg)]);
                } else if ($backend===TG_JS) {
                        crash(`JS`);
                } else {
                    crash("9/0"); // unknown $backend
                }
                $ctrl_xtra = $repe($ctrl_xtra,$DX_CAPTURE,id,["sequence",dlg]);
            } else if (equal(res,`RELEASE`)) {
                if ($backend===TG_GTK) {
                    c_proc($x_gtk_grab_remove,["sequence",$subse($ctrl_handles,dlg)]);
                } else if ($backend===TG_WINAPI) {
                    c_proc($xReleaseCapture,["sequence"]);
                } else if ($backend===TG_JS) {
                        crash(`JS`);
                } else {
                    crash("9/0"); // unknown $backend
                }
                $ctrl_xtra = $repe($ctrl_xtra,$DX_CAPTURE,NULL,["sequence",dlg]);
            } else {
                crash("9/0"); // unknown string res
            }
            res = TG_IGNORE;
        }
        if (equal(res,TG_CLOSE)) {
            $gHide(gGetDialog(id));
        }
        return res;
    }
    return TG_CONTINUE;
} $tg_click_handler.$sig="FOPII";
