/*local*/ function $tg_plot(/*gcp*/ canvas, /*atom*/ x, y, c, /*bool*/ bFlip=false) {
    //  plot the pixel at (x, y) with brightness c (where 0 <= c <= 1)
    //  note that bFlip is exclusively intended for $tg_wu_line() only.
    //  aside: c is 0 or 1 ~0.5% of the time, so attempting to optimise
    //         for that would only succeed in slowing everything down.
    if (bFlip) { [,x,y] = ["sequence",y,x]; }
    let /*integer*/ ic = floor(c*256), 
                    iC = 256-ic;
    let /*integer*/ bg = $gGetPixel(canvas,x,y);
    let /*integer*/ rB = and_bits(bg,0xFF0000)/0x10000, 
                    gB = and_bits(bg,0xFF00)/0x100, 
                    bB = and_bits(bg,0xFF);
    let /*integer*/ r = and_bits(($rL*ic+rB*iC)/256,0xFF), 
                    g = and_bits(($gL*ic+gB*iC)/256,0xFF), 
                    b = and_bits(($bL*ic+bB*iC)/256,0xFF);
    $gDrawPixel(canvas,x,y,(r*0x10000+g*0x100)+b);
} $tg_plot.$sig="PINNNI,1";
