/*local*/ function $tg_plot2(/*gcp*/ canvas, /*atom*/ x, y, f, xgap, /*integer*/ width, /*bool*/ bFlip) {
    let /*integer*/ d = floor(width/2);
    $tg_plot(canvas,x,y-d,(1-f)*xgap,bFlip);
    if (d===0) {
        $tg_plot(canvas,x,y+1,f*xgap,bFlip);
    } else {
        for (let i=-d+1, i$lim=d-1; i<=i$lim; i+=1) {
            $tg_plot(canvas,x,y+i,1,bFlip);
        }
        $tg_plot(canvas,x,y+d,f*xgap,bFlip);
    }
} $tg_plot2.$sig="PINNNNII";

