/*local*/ function $tg_wu_line(/*gcp*/ canvas, /*atom*/ x1, y1, x2, y2, colour, /*integer*/ width, /*object*/ style) {
    $tg_wu_set_rgbL(colour);
    let /*bool*/ flip = compare(abs(y2-y1),abs(x2-x1))>0; // (aka steep)
    if (flip) {
        [,x1,y1,x2,y2] = ["sequence",y1,x1,y2,x2];
    }
    if (x1>x2) {
        [,x1,x2,y1,y2] = ["sequence",x2,x1,y2,y1];
    }
    let /*atom*/ dx = x2-x1, 
                 dy = y2-y1, 
                 gradient = ((dx===0) ? 1 : dy/dx), 
                 x1end = round(x1), 
                 x2end = round(x2), 
                 y1end = y1+gradient*(x1end-x1), 
                 y2end = y2+gradient*(x2end-x2);
    let /*integer*/ dots = 1;
    let /*sequence*/ dasher = ((sequence(style)) ? style : $subse($dashers,style));
    // handle first endpoint
    $tg_plot2(canvas,x1end,floor(y1end),$fpart(y1end),1-$fpart(x1+.5),width,flip);
    // main loop
    let /*atom*/ intery = y1end+gradient; // first y-intersection for the main loop
    for (let x=x1end+1, x$lim=x2end-1; x<=x$lim; x+=1) {
        dots = ((equal(dots,length(dasher))) ? 1 : dots+1);
        if ($subse(dasher,dots)) {
            $tg_plot2(canvas,x,floor(intery),$fpart(intery),1,width,flip);
        }
        intery += gradient;
    }
    // handle second endpoint
    $tg_plot2(canvas,x2end,floor(y2end),$fpart(y2end),$fpart(x2+.5),width,flip);
} $tg_wu_line.$sig="PINNNNNIO";
