function $plot_aa(/*gcp*/ canvas, /*atom*/ x, y) {
    let /*integer*/ ix = floor(x), nx = ix+1, 
                    iy = floor(y), ny = iy+1;
    let /*atom*/ fx = x-ix, gx = 1-fx, 
                 fy = y-iy, gy = 1-fy;
    $tg_plot(canvas,ix,iy,gx*gy);
    $tg_plot(canvas,nx,iy,fx*gy);
    $tg_plot(canvas,ix,ny,gx*fy);
    $tg_plot(canvas,nx,ny,fx*fy);
} $plot_aa.$sig="PINN";
