/*global*/ function gRotatePolygon(/*sequence*/ poly, /*object*/ angle) {
//
//  DEV this is a fair bit slower than I thought it would be...
//  In demo\theGUI\gDrawPolygon.exw the Phix logo with 33 {x,y}
//  rotates worse than twice as slowly as the house with 5 {x,y}
//  whereas I expected it would be keyboard-repeat-rate bound...
//
//  Update: there is a 10* faster #ilASM{} version of this in 
//         demo\theGUI\gDrawPoly.exw in case it is ever needed.
//
    let /*atom*/ cx, cy;
    if (sequence(angle)) {
        [,angle,cx,cy] = angle;
    } else {
        [,cx,cy] = $subse(poly,1);
    }
    if (!equal(angle,0)) {
        let /*integer*/ lp = length(poly);
        let /*sequence*/ res = repeat(0,lp);
        let /*atom*/ rr = angle*TG_DEG2RAD, 
                     sr = sin(rr), 
                     cr = cos(rr);
        for (let i = 1, pi$lim = length(poly); i <= pi$lim; i += 1) { let pi = $subse(poly,i);
            let /*integer*/ lpi = length(pi);
            if (lpi===0) {
                res = $repe(res,i,["sequence"]);
            } else if (lpi>=8) {
                crash(`arc segments not supported`,{},2);
            } else if (odd(lpi)) {
                crash(`odd segment length found`,{},2);
            } else {
                let /*sequence*/ ri = repeat(0,lpi);
                for (let j=1, j$lim=lpi-1; j<=j$lim; j+=2) {
                    let /*integer*/ k = j+1;
                    let /*atom*/ x = $subse(pi,j)-cx, 
                                 y = $subse(pi,k)-cy;
                    // counter-clockwise:
//                  {x,y} = {y*s + x*c + cx, 
//                           y*c - x*s + cy}
                    // clockwise:
//                  {x,y} = {x*c - y*s + cx, 
//                           x*s + y*c + cy}
//                  pi[j] = x
//                  pi[k] = y
//                  pi[j] = x*c - y*s + cx
//                  pi[k] = x*s + y*c + cy
                    ri = $repe(ri,j,(x*cr-y*sr)+cx);
                    ri = $repe(ri,k,(x*sr+y*cr)+cy);
                }
                res = $repe(res,i,ri);
            }
        }
        return res;
    }
    return poly;
} gRotatePolygon.$sig="FPO";
function $ellipse_point(/*atom*/ xc, yc, a, b, cr, sr, t) {
    let /*atom*/ ct = cos(t), 
                 st = sin(t);
    return ["sequence",(xc+(a*ct)*cr)-(b*st)*sr,(yc+(a*ct)*sr)+(b*st)*cr];
} $ellipse_point.$sig="FNNNNNNN";
