/*local*/ function $tg_Init() {
    $clear_tables();
    $bInit = true;
    $handlers = new_dict();      // key is {gdx,name}, data is integer routine_id
    $handler_sigs = new_dict();  // key is {ct,name}, data is sig
    $leaf_only = new_dict();     // key is name, data is [only ever] true
    let /*bool*/ L = equal(platform(),LINUX), 
                 bWinders = equal(platform(),WINDOWS);
    let /*integer*/ MB = machine_bits();
    let /*atom*/ KERNEL32, USER32;
    if (equal(platform(),WINDOWS)) {
        KERNEL32 = open_dll(`kernel32.dll`);
        USER32 = open_dll(`user32.dll`);
        $xCloseClipboard = define_c_proc(USER32,`CloseClipboard`,["sequence"]);
                        //  (void)
//          C_BOOL)     -- BOOL (0 on failure)
        $xEmptyClipboard = define_c_func(USER32,`EmptyClipboard`,["sequence"],C_BOOL); // BOOL
        $xGetClipboardData = define_c_func(USER32,`GetClipboardData`,["sequence",C_UINT],C_PTR); // HANDLE
        $xGlobalAlloc = define_c_func(KERNEL32,`GlobalAlloc`,["sequence",C_UINT,C_UINT],C_PTR); // HGLOBAL
        $xGlobalFree = define_c_func(KERNEL32,`GlobalFree`,["sequence",C_PTR],C_PTR); // HGLOBAL (null on success)
        $xGlobalLock = define_c_func(KERNEL32,`GlobalLock`,["sequence",C_PTR],C_PTR); // LPVOID
        $xGlobalSize = define_c_func(KERNEL32,`GlobalSize`,["sequence",C_PTR],C_INT); // SIZE_T
        $xGlobalUnlock = define_c_proc(KERNEL32,`GlobalUnlock`,["sequence",C_PTR]); //  HGLOBAL hMem
//          C_BOOL)     -- BOOL (non-0: success but still locked, 0: check success/failure via GetLastError)
        $xIsClipboardFormatAvailable = define_c_func(USER32,`IsClipboardFormatAvailable`,["sequence",C_UINT],C_BOOL); // BOOL
        $xOpenClipboard = define_c_func(USER32,`OpenClipboard`,["sequence",C_PTR],C_BOOL); // BOOL
        $xSetClipboardData = define_c_func(USER32,`SetClipboardData`,["sequence",C_UINT,C_PTR],C_INT); // HANDLE (NULL means failure)
        let /*integer*/ idCIEXYZ, idCIEXYZTRIPLE; // (not needed past define $idBITMAPV5HEADER)
        idCIEXYZ = define_struct(`typedef struct tagCIEXYZ {
                                      FXPT2DOT30 ciexyzX;
                                      FXPT2DOT30 ciexyzY;
                                      FXPT2DOT30 ciexyzZ;
                                    } CIEXYZ;`);
        idCIEXYZTRIPLE = define_struct(`typedef struct tagICEXYZTRIPLE {
                                          CIEXYZ ciexyzRed;
                                          CIEXYZ ciexyzGreen;
                                          CIEXYZ ciexyzBlue;
                                        } CIEXYZTRIPLE;`);
        $idBITMAPV5HEADER = define_struct(`typedef struct {
                                              DWORD        bV5Size;
                                              LONG         bV5Width;
                                              LONG         bV5Height;
                                              WORD         bV5Planes;
                                              WORD         bV5BitCount;
                                              DWORD        bV5Compression;
                                              DWORD        bV5SizeImage;
                                              LONG         bV5XPelsPerMeter;
                                              LONG         bV5YPelsPerMeter;
                                              DWORD        bV5ClrUsed;
                                              DWORD        bV5ClrImportant;
                                              DWORD        bV5RedMask;
                                              DWORD        bV5GreenMask;
                                              DWORD        bV5BlueMask;
                                              DWORD        bV5AlphaMask;
                                              DWORD        bV5CSType;
                                              CIEXYZTRIPLE bV5Endpoints;
                                              DWORD        bV5GammaRed;
                                              DWORD        bV5GammaGreen;
                                              DWORD        bV5GammaBlue;
                                              DWORD        bV5Intent;
                                              DWORD        bV5ProfileData;
                                              DWORD        bV5ProfileSize;
                                              DWORD        bV5Reserved;
                                            } BITMAPV5HEADER, *PBITMAPV5HEADER;`);
    }
          $js_re_am = new RegExp("&","g");
          $js_re_sp = new RegExp("[ ]","g");

    // finally setup common $handlers:
    $tg_register_handler(0,`KEY`,["sequence",`FOI`,`FOII`,`FOIII`,`FOIIII`,`FOIIIII`,`POI`,`POII`,`POIII`,`POIIII`,`POIIIII`]);
    $tg_register_handler(0,`CLICK`,["sequence",`FOPII`,`POPII`,`FOP`,`POP`],true);
    $tg_register_handler(0,`REDRAW`,["sequence",`PO`,`POII`,`POIIII`]);
    // aside: `MOUSEMOVE` now handled specially, rather than specify 20 sigs here.
    $tg_register_handler(0,`MOUSEWHEEL`,["sequence",`POI`,`POII`,`POIII`,`POIIII`],true);
    $tg_register_handler(0,`MOUSELEAVE`,["sequence",`PO`,`P`],true);
    if ($run_unit_tests) {
        let /*sequence*/ r = include_files();
        let /*integer*/ k = find(`hGUI.e`,vslice(r,2));
        if (equal($subse($subse(r,k),1),$subse($subse(r,1),1))) { // main file in demo\theGUI\?
            $tg_unit_tests();
        }
    }
} $tg_Init.$sig="P";

/*local*/ let /*rtn*/ $idle_rtn = NULL;

/*local*/ let /*sequence*/ $idle_args = ["sequence"];

/*local*/ let /*atom*/ $gtk_idle_id;

/*local*/ let /*bool*/ $idle_low;

/*local*/ let /*sequence*/ $idle_stack = ["sequence"], 
                           $idle_params = ["sequence"], 
                           $low_priorities = ["sequence"];

/*local*/ function $hg_pop_or_prioritise_idle_stack() {
    let /*bool*/ bAlreadyRunning = false;
    let /*integer*/ n = find(false,$low_priorities);
    if ((($idle_rtn!==NULL) && $idle_low) && n) {
        // park the low-priority one ...
        $idle_stack = append($idle_stack,$idle_rtn);
        $idle_params = append($idle_params,$idle_args);
        $low_priorities = append($low_priorities,true);
        // ... and blag a normal priority one
        $idle_rtn = NULL;
        bAlreadyRunning = true; // [no g_idle_add() rqd]
    }
    if (($idle_rtn===NULL) && length($idle_stack)) {
        if (n && $subse($low_priorities,1)) {
            [,$idle_stack[1],$idle_stack[n]] = ["sequence",$subse($idle_stack,n),$subse($idle_stack,1)];
            [,$idle_params[1],$idle_params[n]] = ["sequence",$subse($idle_params,n),$subse($idle_params,1)];
            [,$low_priorities[1],$low_priorities[n]] = ["sequence",$subse($low_priorities,n),$subse($low_priorities,1)];
        }
        $idle_rtn = $subse($idle_stack,1);
        $idle_args = $subse($idle_params,1);
        $idle_low = $subse($low_priorities,1);
        $idle_stack = $subss($idle_stack,2,-1);
        $idle_params = $subss($idle_params,2,-1);
        $low_priorities = $subss($low_priorities,2,-1);
        return !bAlreadyRunning;     // [g_idle_add() rqd?]
    }
    return false; // [no g_idle_add() rqd]
} $hg_pop_or_prioritise_idle_stack.$sig="F"; // $hg_pop_or_prioritise_idle_stack

/*local*/ function $gtk_idle_func(/*atom*/ /*data*/anon1) {
    if ($idle_rtn) {
        let /*integer*/ r = call_func($idle_rtn,$idle_args);
        if (r===TG_IGNORE) {
            $idle_rtn = NULL;
            /*[,] =*/ $hg_pop_or_prioritise_idle_stack();
            return $idle_rtn!==NULL;
        } else if (r!==TG_CONTINUE) {
            crash(`TG_IGNORE or TG_CONTINUE only`);
        }
        return true; // keeps the idle
    }
    return false; // removes the idle
} $gtk_idle_func.$sig="FN";

/*local*/ let /*atom*/ $gtk_idle_func_cb = NULL;

/*global*/ function gGetGlobalIntInt(/*string*/ name) {
    if (!$bInit) { $tg_Init(); }
    if (equal(name,`MOUSEPOS`)) {
        return $tg_get_mousepos();
    } else if (equal(name,`SCREENSIZE`)) {
        return $tg_get_screensize();
    }
    crash(`gGetGlobalIntInt(%s) not supported`,["sequence",name]);
} gGetGlobalIntInt.$sig="FS";
