/*local*/ function $dword_seq(/*object*/ s) { // (technically qword_seq on 64-bit)
    return sequence(s) && !string(s);
} $dword_seq.$sig="TO";

/*local*/ function $paranormalise_traa(/*object*/ title, click, /*sequence*/ attributes, /*$dword_seq*/ args) {
// used by gButton([nullable_string title=NULL,] [rtn click=NULL,] string attributes=``, sequence args={})
// and gCheckbox(), gLink(), gMenuItem(), and gValuator(). (See the docs for the full details)
// This routine is designed to crash on the slightest oddity, hopefully with a decent easily understood message.
    let /*integer*/ nFrames = 3; // (change this back to 1 to debug)
//  integer nFrames = 1 -- (change this back to 1 to debug)
    if (!nullable_string(title)) {
        // assume title omitted (and at least one other parameter passed)
        if (atom(title)) {  // (and, of course, title is not NULL here)
            // assume gButton(click,[attributes[,args]])                -- (intended)
            //                ^title ^click      ^attributes            -- (actual)
            assert(equal(args,["sequence"]),`original_default`,{},nFrames);
            if (length(attributes)) {  // (args really?)
                args = attributes;                                      // (verified $dword_seq now)
                attributes = click;                                     // (verified string below)
            } else if (string(click)) {
                attributes = click;                                     // (verified string below)
            } else {
                asserteq(click,NULL,"",{},nFrames);                     // something odd passed?
            }
            click = title;                                              // (verified rtn below)
            title = NULL;
        } else {
            // assume gButton(attributes[,args])                        -- (intended)
            //                ^title      ^click                        -- (actual)
            asserteq(attributes,``,`original default`,{},nFrames);
            asserteq(args,["sequence"],`original default`,{},nFrames);
            if (sequence(click)) {  // (args really?)
                args = click;                                           // (verified $dword_seq now)
            }
            attributes = title;                                         // (verified string below)
            click = NULL;
            title = NULL;
        }
    } else if (string(click)) {
        // assume gButton(title,attributes[,args]))                     -- (intended)
        //                      ^click      ^attributes                 -- (actual)
        if (!string(attributes)) {     // (args really?)
            args = attributes;                                          // (verified $dword_seq now)
        }
        attributes = click;                                             // (verified string below)
        click = NULL;
    } else if (sequence(click)) { // (and not string)
        // assume gButton(attributes,args)                              -- (intended)
        //                ^title     ^click                             -- (actual)
        asserteq(args,["sequence"],`original default`,{},nFrames);
        asserteq(attributes,``,`original default`,{},nFrames);
        attributes = title;                                             // (verified string below)
        args = click;                                                   // (verified $dword_seq now)
        title = NULL;
        click = NULL;
//  else assume 3 or 4 parameters were passed (title,click,attributes[,args])
    }
    if ((((equal(click,NULL)) && (equal(attributes,``))) && string(title)) && find(0X3D,title)) {
        attributes = title;
//      title = `` -- tweaked 20/5/26
        title = NULL;
    }
    assert(nullable_string(title),`not nullable_string title`,{},nFrames);
    assert(rtn(click),`not rtn click`,{},nFrames);
    assert(string(attributes),`not string attributes`,{},nFrames);
    if (!equal(length(trim(attributes)),0)) {
        assert(find(0X3D,attributes),`'=' missing from attributes`,{},nFrames);
    }
//  assert($dword_seq(args),nFrames:=nFrames)                            -- (ple/autoverified)
    if (equal(attributes,``)) {
        asserteq(args,["sequence"],`original default`,{},nFrames);
    }
    return ["sequence",title,click,attributes,args];
} $paranormalise_traa.$sig="FOOPO";
