    $ctrl_set_attr = $repe($ctrl_set_attr,$TIMER,$tg_set_timer_attribute);
    $ctrl_get_attr = $repe($ctrl_get_attr,$TIMER,$tg_get_timer_attribute);
    if (action!==NULL) { gSetHandler(timer,`ACTION`,action); }
