/*local*/ function $tg_set_graph_attribute(/*gdx*/ id, /*string*/ name, /*object*/ v, /*integer*/ nFrames) {
    let /*integer*/ gxdx = find(name,$grph_attr_names);
    if (gxdx) {
        // aside: common up by type, but feel free to do  
        // anything that needs special treatment by name
        let /*integer*/ vtype = $subse($grph_attr_types,gxdx);
        if (vtype===0X42) {
            v = $tg_to_bool(v,nFrames+2);
        } else if (vtype===0X43) {
            v = $tg_get_colour_value(v);
            assert(atom(v));
        } else if (vtype===0X49) {
            if (string(v) && is_integer(v)) {
                v = to_integer(v);
            } else {
                assert(integer(v),"",{},nFrames+2);
            }
        } else if (vtype===0X4E) {
            if (string(v)) { v = to_number(v); }
            assert(atom(v),"",{},nFrames+2);   // (fail if `` yields {})
        } else if (vtype===0X53) {
            assert(string(v));
        } else if (equal(name,`LEGENDXY`)) {
            if (string(v)) { v = $tg_intint(v,name,nFrames+2); }
            assert((sequence(v) && !string(v)) && (equal(length(v),2)));
        } else if (vtype===0X50) {
            assert(sequence(v));
        } else if (vtype!==0X4F) {
            crash("9/0");
        }
        $ctrl_xtra = $repe($ctrl_xtra,gxdx,v,["sequence",id]);
        return true;
    }
    return false;
} $tg_set_graph_attribute.$sig="FOSOI";
function $tg_get_graph_attribute(/*gdx*/ id, /*string*/ name, /*integer*/ nFrames) {
    let /*integer*/ gxdx = find(name,$grph_attr_names);
    if (gxdx) {
        return $subse($subse($ctrl_xtra,id),gxdx);
    }
    $tg_bad_attr(id,name,nFrames+1);
} $tg_get_graph_attribute.$sig="FOSI";

