/*local*/ let /*sequence*/ $menu_images = ["sequence"]; // from tg_xpm.e/`chk_xpm` (when/if actually needed).

/*local*/ function $tg_draw_one_menu(/*gdx*/ menu, /*gdm*/ img, /*sequence*/ items, mxtra) {
    let /*integer*/ w = $subse(mxtra,$MX_WIDTH), 
                    h = $subse(mxtra,$MX_HEIGHT), 
                    kb = $subse(mxtra,$MX_KEYMODE), 
                    hot_item = $subse(mxtra,$MX_HOT), 
                    hh = floor($TG_MENUITEM_HEIGHT/2), 
                    y = 4;
    let /*bool*/ bAnyImages = false;
    for (let item$idx = 1, item$lim = length(items); item$idx <= item$lim; item$idx += 1) { let item = $subse(items,item$idx);
        if (!equal($subse(item,$MX_IMAGE),NULL)) {
            bAnyImages = true;
            break;
        }
    }
    for (let i = 1, item$lim = length(items); i <= item$lim; i += 1) { let item = $subse(items,i);
        let /*string*/ text = $subse(item,$MX_TEXT), shortcutkey;
        if (equal(text,`-`)) {
            y += 3;
            gDrawLine(img,4,y,w-4,y,$TG_MENUSEP_FGCLR);
            y += 3;
        } else {
            if (i===hot_item) {
                if (kb) {
                    gDrawRect(img,3,y,w-3,y+$TG_MENUITEM_HEIGHT,false,0,TG_BLACK);
                } else {
                    gDrawRect(img,0,y,w-1,y+$TG_MENUITEM_HEIGHT,true,0,$TG_MENUHOV_BGCLR);
                }
            }
            let /*bool*/ enabled = $subse(item,$MX_ENABLED);
            let /*integer*/ submenu = $subse(item,$MX_SUBMENU);
            if (submenu && (equal(length($subse(gMenuGetAttribute(menu,submenu,`DATA`),$MX_ITEMS)),0))) {
                enabled = false;
            }
            let /*object*/ image = $subse(item,$MX_IMAGE);
            if (string(image)) {
                if (equal(length($menu_images),0)) {
                    $menu_images = gGetGlobal(`chk_xpm`);
                    // {$ucb,$ccb,$urb,$crb,$irb}
                }
                let /*bool*/ checked = $subse(item,$MX_CHECKED);
                let /*integer*/ l = length(image);
                image = $subse($menu_images,(l*2-1)+checked);
                if (!enabled) {
                    image = ((l===2) ? $subse($menu_images,5) : gGreyscale_XPM(image));
                }
            }
            if (image) {
                let /*integer*/ [,iw,ih] = gGetAttribute(image,`SIZE`);
                gDrawImage(image,img,16-iw/2,(y+hh)-ih/2);
            }
            let /*integer*/ k = find(0X9,text), 
                            id = $subse(item,$MX_ID);
            if (k) {
                shortcutkey = $subss(text,k+1,-1);
                text = $subss(text,1,k-1);
                if (shortcutkey==="") {
                    if (!and_bits(id,$M_NOT_KEY)) {
                        shortcutkey = sprintf(`(%s)`,gGetKeyName(id));
                    } else {
                        k = 0; // (don't show it then)
                    }
                }
            }
            let /*atom*/ clr = 
                               ((i===hot_item) ? $TG_MENUHOV_FGCLR : ((enabled) ? TG_BLACK : TG_DARK_GREY));
            gDrawText(img,((bAnyImages) ? 30 : 7),y+hh,text,{},TG_E,0,clr);
            if (submenu) {
//$menu_images[6]?
                gDrawText(img,w-16,y+hh,`>`,{},TG_E,0,clr);
            } else if (k) {
//              gDrawText(img,w-6,y+hh,shortcutkey,align:=TG_W,colour:=clr,style:=$TG_MENU_KEY_FONT)
                gDrawText(img,w,y+hh,shortcutkey,{},TG_W,0,clr,$TG_MENU_KEY_FONT);
            }
            y += $TG_MENUITEM_HEIGHT;
        }
    }
    gDrawRect(img,0,0,w-1,h-1,false,0,0xE5E5E5);
} $tg_draw_one_menu.$sig="POIPP";
$draw_menu = $tg_draw_one_menu; // overrideable via gSetGlobal(`drawmenu`), for hMenu.exw

