/*global*/ function gMenu(/*sequence*/ children, /*rtn*/ handler) {
    // convert from nested form, or assume already in internal form
    let /*sequence*/ menus = ((string($subse($subse(children,1),1))) ? $tg_build_menu(["sequence"],children) : children);
    let /*integer*/ lm = length(menus);
    let /*gdx*/ menu = gCanvas($tg_draw_menubar);
    $ctrl_types = $repe($ctrl_types,menu,$MENU);
    $tg_register_handler($MENU,`HANDLER`,["sequence",`FOII`,`FOI`,`POII`,`POI`]);
    let /*object*/ menu_attr = repeat(0,$CX_MENU_LEN);
    menu_attr = $repe(menu_attr,$CX_MENUS,menus); // w,h,keybd,hot,sel,Ownr,hWnd,hWgt,x,y,img,widths:
    menu_attr = $repe(menu_attr,$CX_MEXTRA,repeat(["sequence",0,0,NULL,NULL,NULL,false,0,0,0,0,NULL,NULL],lm));
    $ctrl_xtra = $repe($ctrl_xtra,menu,menu_attr);
    menu_attr = 0;
    for (let mdx=1, mdx$lim=lm; mdx<=mdx$lim; mdx+=1) {
        $tg_compute_menu_size(menu,mdx);
    }
    gSetAttribute(menu,`BGCLR`,TG_WHITE);
    gSetAttribute(menu,`FONT`,$TG_MENU_FONT);
    gSetAttribute(menu,`EXPAND`,`HORIZONTAL`);
    gSetAttribute(menu,`SIZE`,["sequence",0,20]);
    gSetAttribute(menu,`BGCLR`,$TG_MENUBAR_BGCLR);
    gSetHandler(menu,`MOUSEMOVE`,$tg_menubar_mousemove);
    gSetHandler(menu,`MOUSELEAVE`,$tg_menubar_mouseleave);
    gSetHandler(menu,`CLICK`,$tg_menubar_click);
    gSetHandler(menu,`HANDLER`,handler);
    return menu;
} gMenu.$sig="FPI";

