/*local*/ function $tg_GTK_popup_expose(/*atom*/ widget, /*event*/anon1, /*integer*/ mdx) {
    // GTK2 version, which needs to create a cairo context to draw on.
    //  (then invokes GTK3 version, passing said cairo just created)
    let /*$nnatom*/ win = c_func($x_gtk_widget_get_window,["sequence",widget]), 
                   cairo = c_func($x_gdk_cairo_create,["sequence",win]);
    let /*integer*/ res = $tg_GTK_popup_draw(widget,cairo,mdx);
    c_proc($x_cairo_destroy,["sequence",cairo]);
    return res;
} $tg_GTK_popup_expose.$sig="FNNI";

/*local*/ function $tg_GTK_popup_click(/*atom*/ widget, /*atom*/ event, /*integer*/ popup) {
    let /*integer*/ button = get_struct_field($idGdkEventButton,event,`button`);
    if (button===1) { // left
        return $tg_gtk_click(widget,event,popup);
    }
    return true;
} $tg_GTK_popup_click.$sig="FNNI";
function $tg_popup_leave(/*gdx*/ popup) {
    let /*integer*/ ct = $subse($ctrl_types,popup);
    if (equal(ct,$LIST)) {
        $tg_list_mouseleave(popup);
    } else if (equal(ct,$CALENDAR)) {
        $tg_calendar_mouseleave(popup);
    } else {
        crash("9/0");
    }
} $tg_popup_leave.$sig="PO";

/*local*/ function $tg_GTK_popup_leave(/*atom*/ widget, /*atom*/ event, /*integer*/ popup) {
    $tg_popup_leave(popup);
    return true;
} $tg_GTK_popup_leave.$sig="FNNI";

/*local*/ function $PopupWndProc_cb(/*atom*/ hWnd, msg, wParam, lParam) {
    let /*integer*/ popup = $tg_find_popup(hWnd,1);
    if (popup) {  // ignore eg WM_CREATE which can arrive before
                  // very next line can store hWnd in $ctrl_hdc[]
        switch (msg) {
            case $WM_ACTIVATE:  // (not strictly needed, but safer)
                if (equal($LOWORD(wParam),$WA_INACTIVE)) {
                    $tg_hide(popup);
                }
                return 0;
                break;
            case $WM_SETFOCUS:  // (not strictly needed, but safer)
                return 0;
                break;
            case $WM_NCACTIVATE:  // (not strictly needed, but safer)
                return true;
                break;
            case $WM_MOUSEACTIVATE:
                return $MA_NOACTIVATE;
                break;
            case $WM_MOUSEMOVE:
                $tg_WinAPI_MOUSEMOVE(popup,lParam,wParam);
                break;
            case $WM_MOUSELEAVE:
                $tg_popup_leave(popup);
                return 0;
                break;
            case $WM_MOUSEWHEEL: case $WM_MOUSEHWHEEL:
                $tg_WINAPI_mousewheel(popup,msg,lParam,wParam);
                break;
            case $WM_LBUTTONDOWN:
                return $tg_WinAPI_BUTTONDOWN(popup,msg,wParam,lParam,hWnd);
                break;
            case $WM_LBUTTONUP:
                c_proc($xReleaseCapture,["sequence"]);
                break;
            case $WM_PAINT:
                let /*integer*/ w = $subse($subse($ctrl_size,popup),$SZ_USER_W), 
                                h = $subse($subse($ctrl_size,popup),$SZ_USER_H);
                $ctrl_size = $repe($ctrl_size,$SZ_W,w,["sequence",popup]);
                $ctrl_size = $repe($ctrl_size,$SZ_H,h,["sequence",popup]);
                if (equal($subse($ctrl_bg,popup),-1)) {
                    $ctrl_bg = $repe($ctrl_bg,popup,TG_WHITE); }
                $tg_draw_control_images(popup);
                let /*gdm*/ img = $subse($ctrl_images,popup);
                let /*integer*/ imdx = (-img+1)/2, 
                                iw = $subse($subse($gimages,imdx),$TG_IMG_WIDTH), 
                                ih = $subse($subse($gimages,imdx),$TG_IMG_HEIGHT);
                gDrawRect(img,0,0,iw-1,ih-1,false,0,TG_BLACK);
                let /*atom*/ dstDC = c_func($xBeginPaint,["sequence",hWnd,$pPAINTSTRUCT]), 
                             srcDC = $tg_WinAPI_GetSrcDC(), 
                             src_img = $subse($subse($gimages,imdx),$TG_IMG_HANDLE), 
                             prevBM = c_func($xSelectObject,["sequence",srcDC,src_img]);
                $c_funk($xBitBlt,["sequence",dstDC,0,0,w,h,srcDC,0,0,$SRCCOPY]);
                prevBM = c_func($xSelectObject,["sequence",srcDC,prevBM]);
                c_proc($xEndPaint,["sequence",hWnd,$pPAINTSTRUCT]);
                return 0;
                break;
            case $WM_KEYDOWN:
//              -- directly routed as if via this by WndProc:
//              return $tg_calendar_key(popup,key)
// or:          return $tg_list_key(popup,key,ctrl,shift) 
                return 0; // (extra paranoia, let WndProc always do it)
        }
    }
    return c_func($xDefWindowProc,["sequence",hWnd,msg,wParam,lParam]);
} $PopupWndProc_cb.$sig="FNNNN";
let /*bool*/ $bPopupWndProcRegistered = false;

/*local*/ function $tg_popup(/*gdx*/ owner, ctrl) { // (exported via gGetGlobal to hText.exw)
    let /*gdx*/ dlg = gGetDialog(owner);
    let /*integer*/ [,w,h] = gGetIntInt(ctrl,`USERSIZE`),[,ow,oh] = gGetIntInt(owner,`SIZE`),
                    x = $subse($subse($ctrl_size,owner),$SZ_X), 
                    y = $subse($subse($ctrl_size,owner),$SZ_Y);
    y += oh+23;
    if (equal($subse($ctrl_hdc,ctrl),NULL)) {
        $ctrl_hdc = $repe($ctrl_hdc,ctrl,["sequence",NULL,NULL,dlg,w,h]); }
    if ((w===0) || (h===0)) {
        assert(equal($subse($ctrl_types,ctrl),$LIST));
        if (w===0) { w = $subse($subse($ctrl_size,owner),$SZ_W); }
        if (h===0) {
            let /*integer*/ l = min($tg_list_get_data_length(ctrl),10);
            h = $subse(gGetTextExtent(`X`,ctrl),2)*l+2;
        }
        $ctrl_size = $repe($ctrl_size,$SZ_USER_W,w,["sequence",ctrl]);
        $ctrl_size = $repe($ctrl_size,$SZ_USER_H,h,["sequence",ctrl]);
    }
    if (!gGetAttribute(dlg,`MAXIMISED`)) {
        x += $subse($subse($ctrl_size,dlg),$SZ_X)+8;
        y += $subse($subse($ctrl_size,dlg),$SZ_Y)+8;
    }
    if ($screen_width===-1) {
//      {$screen_width,$screen_height} = gGetGlobalIntInt(`SCREENSIZE`)
        [,$screen_width,$screen_height] = $tg_get_screensize(); // ""
    }
    if (compare(x+w,$screen_width)>0) { x = (x+ow)-w; } // flip horizontally
    if (compare(y+h,$screen_height)>0) { y = (y-oh)-h; } // flip vertically
    $ctrl_flags = $repe($ctrl_flags,ctrl,or_bits($subse($ctrl_flags,ctrl),$CF_POPUP));
    $ctrl_xtra = $repe($ctrl_xtra,$DX_ACTIVEPOP,ctrl,["sequence",dlg]);
    let /*atom*/ hWnd = $subse($subse($ctrl_hdc,ctrl),1), hPopup, hDraw, 
                 hOwn = $subse($ctrl_handles,dlg);
    if (hWnd===NULL) {
                crash(`JS`);
    } else {
                crash(`JS`);
    }
            crash(`JS`);
} $tg_popup.$sig="POO";

/*local*/ let /*gdn*/ $stripes = NULL; // [drifting] background image for a gProgressBar.

/*local*/ function $tg_redraw_progressbar(/*gdx*/ pbar, /*integer*/ w, h) {
    let /*gdn*/ img = $subse($subse($ctrl_xtra,pbar),$CX_PROGRESS_IMAGE);
    if ((equal(img,NULL)) || (!equal(gGetAttribute(img,`SIZE`),["sequence",w+15,h]))) {
        if (!equal(img,NULL)) { img = gImageDestroy(img); }
        img = gImage(w+15,h);
        if (equal($stripes,NULL)) {
            $stripes = gImage_from_XPM($tg_XPM_from_shorthand("stripes"));
        }
        let /*integer*/ x = 0;
        while (true) {
            let /*integer*/ y = 0;
            while (true) {
                gDrawImage($stripes,img,x,y);
                y += 15;
                if (y>h) {
                    break;
                }
            }
            x += 15;
            if (compare(x,w+15)>0) {
                break;
            }
        }
        $ctrl_xtra = $repe($ctrl_xtra,$CX_PROGRESS_IMAGE,img,["sequence",pbar]);
    }
    let /*integer*/ drift = $subse($subse($ctrl_xtra,pbar),$CX_PROGRESS_DRIFT);
    let /*atom*/ v = $subse($subse($ctrl_xtra,pbar),$CX_PROGRESS_VALUE), 
                 start = $subse($subse($ctrl_xtra,pbar),$CX_PROGRESS_START), 
                 limit = $subse($subse($ctrl_xtra,pbar),$CX_PROGRESS_LIMIT), 
                 pc = min(((v-start)/(limit-start))*100,100), l = w;
    if (pc>=100) {
        gDrawRect(pbar,0,0,w-1,h-1,true,3,0x198754);
        let /*gdx*/ pbtimer = $subse($subse($ctrl_xtra,pbar),$CX_PROGRESS_TIMER);
        gSetAttribute(pbtimer,"RUN",false);
    } else {
        l = floor(((v-start)/(limit-start))*w);
        gDrawImage(img,pbar,0,0,drift,0,l);
    }
    gDrawText(pbar,l/2,h/2,"%.2f%%",["sequence",pc],TG_C,0,TG_WHITE);
    drift = rmdr(drift+1,15);
    $ctrl_xtra = $repe($ctrl_xtra,$CX_PROGRESS_DRIFT,drift,["sequence",pbar]);
} $tg_redraw_progressbar.$sig="POII";

/*local*/ function $tg_progress_action(/*gdx*/ pbtimer) {
    let /*gdx*/ pbar = $subse($user_data,pbtimer);
    gRedraw(pbar);
} $tg_progress_action.$sig="PO";

/*local*/ function $tg_set_progressbar_attribute(/*gdx*/ pbar, /*string*/ name, /*object*/ v, /*integer*/ nFrames) {
    if (equal(name,`VALUE`)) {
        let /*bool*/ bRun = true;
        if (sequence(v)) {
            switch (length(v)) /*with fallthrough*/ {
                case 4: bRun = $subse(v,4);
                case 3:
                    $ctrl_xtra = $repe($ctrl_xtra,$CX_PROGRESS_START,$subse(v,3),["sequence",pbar]);
                case 2:
                    $ctrl_xtra = $repe($ctrl_xtra,$CX_PROGRESS_LIMIT,$subse(v,2),["sequence",pbar]);
                case 1:
                    $ctrl_xtra = $repe($ctrl_xtra,$CX_PROGRESS_VALUE,$subse(v,1),["sequence",pbar]);
                    break;
                default: 
                    crash("uh?",{},nFrames+2);           // wot len dat den?
            }
            v = $subse(v,1);
        } else {
            $ctrl_xtra = $repe($ctrl_xtra,$CX_PROGRESS_VALUE,v,["sequence",pbar]);
        }
        gRedraw(pbar);
        let /*gdx*/ pbtimer = $subse($subse($ctrl_xtra,pbar),$CX_PROGRESS_TIMER);
        gSetAttribute(pbtimer,"RUN",bRun);
        return true;
    }
    return false;
} $tg_set_progressbar_attribute.$sig="FOSOI";

/*local*/ function $tg_get_progressbar_attribute(/*gdx*/ pbar, /*string*/ name, /*integer*/ nFrames) {
    if (equal(name,`VALUE`)) {
        return $subse($subse($ctrl_xtra,pbar),$CX_PROGRESS_VALUE);
    }
    $tg_bad_attr(pbar,name,nFrames+1);
} $tg_get_progressbar_attribute.$sig="FOSI";

/*global*/ function gProgressBar() {
    let /*gdx*/ pbar = gCanvas($tg_redraw_progressbar), 
                pbtimer = gTimer($tg_progress_action,100,true,pbar);
    $ctrl_types = $repe($ctrl_types,pbar,$PROGRESS);
    $ctrl_set_attr = $repe($ctrl_set_attr,$PROGRESS,$tg_set_progressbar_attribute);
    $ctrl_get_attr = $repe($ctrl_get_attr,$PROGRESS,$tg_get_progressbar_attribute);
    let /*object*/ cx = repeat(0,$CX_PROGRESS_LEN);
//  cx[$CX_PROGRESS_IMAGE] = NULL
//  cx[$CX_PROGRESS_DRIFT] = 0
    cx = $repe(cx,$CX_PROGRESS_TIMER,pbtimer);
//  cx[$CX_PROGRESS_VALUE] = 0
//  cx[$CX_PROGRESS_START] = 0
    cx = $repe(cx,$CX_PROGRESS_LIMIT,100);
    $ctrl_xtra = $repe($ctrl_xtra,pbar,cx);
    cx = 0;
    gSetAttribute(pbar,`BGCLR`,TG_WHITE);
    gSetAttribute(pbar,`EXPAND`,0X48);
    gSetAttribute(pbar,`SIZE`,`x25`);
    return pbar;
} gProgressBar.$sig="F";

/*local*/ let /*gdn*/ $slider_thumb = NULL, $slider_vthumb;

/*local*/ function $tg_draw_slider(/*gdx*/ slider, /*integer*/ w, h) {
    let /*bool*/ bActive = gGetAttribute(slider,`ACTIVE`), 
                 bHoriz = $subse($subse($ctrl_xtra,slider),$CX_SLIDER_HORIZ);
    let /*atom*/ v = $subse($subse($ctrl_xtra,slider),$CX_SLIDER_VALUE);
    if (equal($slider_thumb,NULL)) {
        // (otherwise undocumented, as defined in tg_xpm.e:)
        [,$slider_thumb,$slider_vthumb] = gGetGlobal(`slider_thumb`);
    }
    if (bHoriz) {
        gDrawRect(slider,0,7,w-1,8,true,0,0xE7EAEA);
        gDrawRect(slider,0,6,w-1,9,false,0,0xD6D6D6);
        gDrawImage($slider_thumb,slider,(w-10)*v,0);
        gDrawLine(slider,5,20,5,h-1,0xC4C4C4);
        gDrawLine(slider,w-5,20,w-5,h-1,0xC4C4C4);
    } else {
        gDrawRect(slider,7,0,8,h-1,true,0,0xE7EAEA);
        gDrawRect(slider,6,0,9,h-1,false,0,0xD6D6D6);
        gDrawImage($slider_vthumb,slider,0,(h-10)*v);
        gDrawLine(slider,20,5,w-1,5,0xC4C4C4);
        gDrawLine(slider,20,h-5,w-1,h-5,0xC4C4C4);
    }
} $tg_draw_slider.$sig="POII";

/*local*/ function $tg_slider_mousemove(/*gdx*/ slider, /*integer*/ x, y, /*bool*/ left, middle, right) {
    let /*bool*/ bActive = gGetAttribute(slider,`ACTIVE`), 
                 bDragg = $subse($subse($ctrl_xtra,slider),$CX_SLIDER_DRAGG), 
                 bHoriz = $subse($subse($ctrl_xtra,slider),$CX_SLIDER_HORIZ);
    let /*integer*/ dxy = $subse($subse($ctrl_xtra,slider),$CX_SLIDER_DRAGXY), [,w,h] = gGetAttribute(slider,`SIZE`);
    let /*atom*/ v = $subse($subse($ctrl_xtra,slider),$CX_SLIDER_VALUE);
    if (!left) {     // (DEV maybe mouseleave? maybe not...)
        $ctrl_xtra = $repe($ctrl_xtra,$CX_SLIDER_DRAGG,false,["sequence",slider]);
        let /*bool*/ bOnThumb;
        if (bHoriz) {
            let /*atom*/ tx = (w-10)*v;
            bOnThumb = x>=tx && compare(x,tx+11)<=0;
        } else {
            let /*atom*/ ty = (h-10)*v;
            bOnThumb = y>=ty && compare(y,ty+11)<=0;
        }
        let /*string*/ wens = ((bHoriz) ? `WE_RESIZE` : `NS_RESIZE`);
        gSetAttribute(slider,`CURSOR`,((bOnThumb) ? wens : NULL));
        $ctrl_xtra = $repe($ctrl_xtra,$CX_SLIDER_ONTHUMB,bOnThumb,["sequence",slider]);
    } else if (bDragg) {
        let /*integer*/ xy = ((bHoriz) ? x : y), 
                        wh = ((bHoriz) ? w : h);
        v += (xy-dxy)/(wh-10);
        v = max(min(v,1),0);
        $ctrl_xtra = $repe($ctrl_xtra,$CX_SLIDER_VALUE,v,["sequence",slider]);
        $ctrl_xtra = $repe($ctrl_xtra,$CX_SLIDER_DRAGXY,xy,["sequence",slider]);
        gRedraw(slider);
        let /*rtn*/ value_changed = gGetHandler(slider,`VALUE_CHANGED`);
        if (value_changed) {
            let /*string*/ sig = $tg_get_sig(value_changed);
            let /*atom*/ [,lo,hi] = $subse($subse($ctrl_xtra,slider),$CX_SLIDER_MINMAX);
            v = v*(hi-lo)+lo;
            if (equal(sig,`PON`)) {
                value_changed(slider,v);
            } else if (equal(sig,`PN`)) {
                value_changed(v);
            } else {
                crash("9/0");
            }
        }
    }
} $tg_slider_mousemove.$sig="POIIIII";

/*local*/ function $tg_slider_click(/*gdx*/ slider, /*sequence*/ status, /*integer*/ x, y) {
    if (gGetAttribute(slider,`ACTIVE`)) {
        let /*bool*/ bOnThumb = $subse($subse($ctrl_xtra,slider),$CX_SLIDER_ONTHUMB), 
                     bHoriz = $subse($subse($ctrl_xtra,slider),$CX_SLIDER_HORIZ);
        if (equal($subss(status,1,2),`LS`)) {
            let /*integer*/ dxy = ((bHoriz) ? x : y);
            $ctrl_xtra = $repe($ctrl_xtra,$CX_SLIDER_DRAGG,true,["sequence",slider]);
            $ctrl_xtra = $repe($ctrl_xtra,$CX_SLIDER_DRAGXY,dxy,["sequence",slider]);
            return `CAPTURE`;
        } else if (equal($subss(status,1,2),`LR`)) {
            if ($subse($subse($ctrl_xtra,slider),$CX_SLIDER_DRAGG)) {
                $ctrl_xtra = $repe($ctrl_xtra,$CX_SLIDER_DRAGG,false,["sequence",slider]);
                return `RELEASE`;
            }
        }
    }
    return TG_IGNORE;
} $tg_slider_click.$sig="FOPII";

/*local*/ function $tg_set_slider_attribute(/*gdx*/ slider, /*string*/ name, /*object*/ v, /*integer*/ nFrames) {
    if (equal(name,`VALUE`)) {
        if (sequence(v)) {
            assert(((equal(length(v),2)) && atom($subse(v,1))) && atom($subse(v,2)),"{lo,hi}",{},nFrames+2);
            let /*atom*/ [,lo,hi] = $subse(v,2);
            $ctrl_xtra = $repe($ctrl_xtra,$CX_SLIDER_MINMAX,["sequence",lo,hi],["sequence",slider]);
            v = ($subse(v,1)-lo)/(hi-lo); // (convert to 0.0..1.0)
        }
        assert(atom(v),"",{},nFrames+2);
        $ctrl_xtra = $repe($ctrl_xtra,$CX_SLIDER_VALUE,v,["sequence",slider]);
        return true;
    }
    return false;
} $tg_set_slider_attribute.$sig="FOSOI";

/*local*/ function $tg_get_slider_attribute(/*gdx*/ slider, /*string*/ name, /*integer*/ nFrames) {
    if (equal(name,`VALUE`)) {
        return $subse($subse($ctrl_xtra,slider),$CX_SLIDER_VALUE);
    }
    $tg_bad_attr(slider,name,nFrames+1);
} $tg_get_slider_attribute.$sig="FOSI";

/*global*/ function gSlider(/*object*/ value_changed=NULL, /*sequence*/ attributes="", args=["sequence"]) {
    [,value_changed,attributes,args] = $paranormalise_vaa(value_changed,attributes,args);
    let /*gdx*/ slider = gCanvas($tg_draw_slider,``,{},2);
    $ctrl_types = $repe($ctrl_types,slider,$SLIDER);
    $ctrl_set_attr = $repe($ctrl_set_attr,$SLIDER,$tg_set_slider_attribute);
    $ctrl_get_attr = $repe($ctrl_get_attr,$SLIDER,$tg_get_slider_attribute);
    let /*object*/ cx = repeat(0,$CX_SLIDER_LEN);
//  cx[$CX_SLIDER_HORIZ] = true -- (set below, after SIZE set)
    cx = $repe(cx,$CX_SLIDER_VALUE,0);
    cx = $repe(cx,$CX_SLIDER_MINMAX,["sequence",0,1]);
    $ctrl_xtra = $repe($ctrl_xtra,slider,cx);
    cx = 0;
    if (length(attributes)) {
        gSetAttributes(slider,attributes,args,2);
    }
    let /*integer*/ [,w,h] = gGetAttribute(slider,`USERSIZE`);
    let /*bool*/ bHoriz = (w===0) || ((h!==0) && w>h);
    $ctrl_xtra = $repe($ctrl_xtra,$CX_SLIDER_HORIZ,bHoriz,["sequence",slider]);
    if ((w===0) && (h===0)) {
        gSetAttribute(slider,`SIZE`,`x24`);
    }
    gSetAttribute(slider,`EXPAND`,((bHoriz) ? 0X48 : 0X56));
    gSetHandler(slider,`CLICK`,$tg_slider_click);
    gSetHandler(slider,`MOUSEMOVE`,$tg_slider_mousemove);
    $tg_register_handler($SLIDER,`VALUE_CHANGED`,["sequence",`PON`,`PN`,`POI`,`PI`,`POO`,`PO`]);
    if (!equal(value_changed,NULL)) {
        gSetHandler(slider,`VALUE_CHANGED`,value_changed);
    }
    return slider;
} gSlider.$sig="FOPP,1";

/*local*/ function $tg_draw_sizer(/*gdx*/ sizer, /*integer*/ w, h) {
    // (sizer is the middle bar, rather than the h/vbox container)
    if (gGetAttribute(sizer,`ACTIVE`)) {
        let /*bool*/ bHoriz = gGetInt(gGetParent(sizer),`ORIENTATION`);
        // note the non-expanding w|h must be odd, else
        //  a) this will typecheck due to the 0.5
        //  b) the thing would display lop-sided.
        [,w,h] = ["sequence",w-1,h-1];
        if (bHoriz) { w /= 2; } else { h /= 2; }
        let /*integer*/ [,x,y] = ((bHoriz) ? ["sequence",w,0] : ["sequence",0,h]);
        gDrawLine(sizer,x,y,w,h);
    }
} $tg_draw_sizer.$sig="POII";
