/*local*/ function $tg_crop_text(/*gdx*/ table, /*string*/ txt, /*integer*/ x) {
    // perform a binary chop to find out how many chars of txt fit
    if (x<=5) { return ``; }
    let /*sequence*/ utf32 = utf8_to_utf32(txt);
    let /*integer*/ lo = 0, 
                    hi = length(utf32), 
                    lopos = 5, 
                    hipos = 5+$subse(gGetTextExtent(txt,table),1);
    if (x>=hipos) { return txt; }
    while (compare(hi,lo+1)>0) {
        let /*integer*/ mid = floor((hi+lo)/2);
        // may as well leave these in (never triggered for me)
        if (mid<=lo) { crash("9/0"); }
        if (mid>=hi) { crash("9/0"); }
        let /*integer*/ midpos = 5+$subse(gGetTextExtent(utf32_to_utf8($subss(utf32,1,mid)),table),1);
        if (x<midpos) {
            hi = mid;
            hipos = midpos;
        } else {
            lo = mid;
            lopos = midpos;
        }
    }
    return $conCat(utf32_to_utf8($subss(utf32,1,lo)), `..`);
} $tg_crop_text.$sig="FOSI";
