/*local*/ function $tg_table_sum_to_col(/*integer*/ col, /*sequence*/ actcols, /*object*/ coldrag) {
    let /*integer*/ x = 0, w;
    if (sequence(coldrag)) {
        for (let c$idx = 1, c$lim = length(coldrag); c$idx <= c$lim; c$idx += 1) { let c = $subse(coldrag,c$idx);
            w = $subse(actcols,c);
            if (c===col) { break; }
            x += w;
        }
    } else {
        x = sum($subss(actcols,1,col-1));
        w = $subse(actcols,col);
    }
    return ["sequence",x,w];
} $tg_table_sum_to_col.$sig="FIPO";

