                        selmode = $subse(tbl_attr,$CXTBL_SELMODE), 
                        resize_hov = $subse(tbl_attr,$CXTBL_RESIZEHOV),  // (don't colsort or select when non-zero)
                        resize_sink = $subse(tbl_attr,$CXTBL_RESIZESINK),  // a ddx
                        drag_title = $subse(tbl_attr,$CXTBL_DRAGTITLE),  // (ditto)
                        n_rows = length(data);
