    $ctrl_get_attr = $repe($ctrl_get_attr,$TABLE,$tg_get_table_attribute);
    let /*object*/ tbl_attr = repeat(0,$CXTBL_LEN);
    tbl_attr = $repe(tbl_attr,$CXTBL_BGSEL,0xCCE8FF);
    tbl_attr = $repe(tbl_attr,$CXTBL_BGHOV,0xE5F3FF);
    tbl_attr = $repe(tbl_attr,$CXTBL_COLDRAG,true);
    tbl_attr = $repe(tbl_attr,$CXTBL_COLSIZE,true);
