            let /*integer*/ fb = 
                                 (($backend===TG_GTK) ? h-8 : (($backend===TG_WINAPI) ? h-5 : 9/0));
//          gDrawRect(tabs,x+2,ty+2,x+tw-1,fb,rc:=2,colour:=TG_BLACK,style:=TG_DOTTED)
            gDrawRect(tabs,x+2,ty+2,(x+tw)-1,fb,false,0,TG_BLACK,TG_DOTTED);
