/*local*/ function $tg_tabs_mousemoveleave(/*gdx*/ tabs) {
    gRedraw(tabs);
} $tg_tabs_mousemoveleave.$sig="PO";
function $tg_tabs_click(/*gdx*/ tabs, /*sequence*/ status, /*integer*/ x, y) {
    if (gGetAttribute(tabs,`ACTIVE`)) {
        let /*integer*/ [,w,h] = gGetAttribute(tabs,`SIZE`), tdx = -2, 
                        old_posn = $subse($subse($ctrl_xtra,tabs),$CXTAB_SEL), 
                        firsttab = $subse($subse($ctrl_xtra,tabs),$CXTAB_1ST);
        let /*bool*/ doleft = false, 
                     doright = false, 
                     doclose = false, 
                     dochange = false, 
                     doredraw = true, 
                     bClose = $subse($subse($ctrl_xtra,tabs),$CXTAB_CLOSE), 
                     rover_needed = $subse($subse($ctrl_xtra,tabs),$CXTAB_ROVER);
        if (((equal($subss(status,1,2),`LS`)) && y>2) && y<22) {
            if ((firsttab>1 && x>=0) && x<10) {
                doleft = true;
                tdx = -1;
            } else if ((rover_needed && x>=w-10) && x<w) {
                doright = true;
                tdx = 0;
            } else {
                let /*integer*/ tx = ((firsttab>1) ? 10 : 0);
                let /*sequence*/ twsave = $subse($subse($ctrl_xtra,tabs),$CXTAB_TWSAVE);
                for (let i = 1, rhs$lim = length(twsave); i <= rhs$lim; i += 1) { let rhs = $subse(twsave,i);
                    tx += rhs;
                    if (x<=tx) {
                        tdx = (firsttab+i)-1;
                        doclose = bClose && tx-x<=10;
                        dochange = !doclose;
                        break;
                    }
                }
                if ((tdx===-2) && rover_needed) {
                    doright = true;
                    tdx = 0;
                }
            }
        }
/*
--NB: "LS" check must occur below this, which must occur after tdx determined:
    rtn tabclick = gGetHandler(tabs,`TABCLICK`)
    if tabclick then
        integer res = tabclick(tabs,status,x,y,tdx,action='X')
        if res=TG_IGNORE then return end if
        assert(res=TG_CONTINUE or res=TG_DEFAULT)
    end if
*/
        if (doleft) {
            firsttab -= 1;
            $ctrl_xtra = $repe($ctrl_xtra,$CXTAB_1ST,firsttab,["sequence",tabs]);
        } else if (doright) {
            firsttab += 1;
            $ctrl_xtra = $repe($ctrl_xtra,$CXTAB_1ST,firsttab,["sequence",tabs]);
        } else if (doclose) {
            [,old_posn,tdx,dochange] = ["sequence",tdx,0,true];
        } else if (dochange) {
            $ctrl_xtra = $repe($ctrl_xtra,$CXTAB_SEL,tdx,["sequence",tabs]);
        } else {
            doredraw = false;
        }
        if (doredraw) {
            // allow bump: show as many tabs as you can while ensuring sel is visible,
            //       however that can disable l/r arrow buttons, so they set it false, 
            //       & it can be annoying for close to jump back, so that does so too.
            $ctrl_xtra = $repe($ctrl_xtra,$CXTAB_BUMP,dochange && (tdx!==0),["sequence",tabs]);
            gRedraw(tabs);
        }
        if (dochange && (old_posn!==tdx)) {
            if (!$tg_tab_change(tabs,old_posn,tdx) && doclose) {
                crash(`TABCHANGED not defined`);
            }
        }
    }
} $tg_tabs_click.$sig="POPII";

/*local*/ function $tg_tabs_key_handler(/*gdx*/ tabs, /*integer*/ c) {
    if (gGetAttribute(tabs,`ACTIVE`)) {
        let /*integer*/ selected = $subse($subse($ctrl_xtra,tabs),$CXTAB_SEL), 
                        firsttab = $subse($subse($ctrl_xtra,tabs),$CXTAB_1ST);
        let /*bool*/ bRedraw = false;
        if (c===VK_LEFT) {
            if (selected>1) {
                selected -= 1;
                if (firsttab>selected) {
                    firsttab = selected;
                    $ctrl_xtra = $repe($ctrl_xtra,$CXTAB_1ST,firsttab,["sequence",tabs]);
                }
                bRedraw = true;
            }
        } else if (c===VK_RIGHT) {
            let /*sequence*/ tabset = $tg_tabs_get_tabset(tabs);
            if (compare(selected,length(tabset))<0) {
                selected += 1;
                bRedraw = true;
            }
        }
        if (bRedraw) {
            $ctrl_xtra = $repe($ctrl_xtra,$CXTAB_SEL,selected,["sequence",tabs]);
            $ctrl_xtra = $repe($ctrl_xtra,$CXTAB_BUMP,true,["sequence",tabs]);
            gRedraw(tabs);
            return TG_IGNORE;
        }
    }
    return TG_CONTINUE;
} $tg_tabs_key_handler.$sig="FOI";

/*local*/ function $tg_set_tabs_attribute(/*gdx*/ tabs, /*string*/ name, /*object*/ v, /*integer*/ nFrames) {
    if (equal(name,`POSN`)) {
        if (string(v)) { v = to_integer(v); }
        let /*integer*/ l = length($tg_tabs_get_tabset(tabs));
        assert(compare(v,1)>=0 && compare(v,l)<=0,"bad POSN",{},nFrames+2);
        $ctrl_xtra = $repe($ctrl_xtra,$CXTAB_SEL,v,["sequence",tabs]);
    } else if (equal(name,`SHOWCLOSE`)) {
        if (string(v)) { v = $tg_to_bool(v,nFrames+2); }
        if (!integer($subse($subse($ctrl_xtra,tabs),$CXTAB_ITEMS)) && (equal(v,true))) {
            crash(`SHOWCLOSE:=true invalid on static tabitems`,{},nFrames+2);
        }
        $ctrl_xtra = $repe($ctrl_xtra,$CXTAB_CLOSE,v,["sequence",tabs]);
    } else {
        return false;
    }
    return true;
} $tg_set_tabs_attribute.$sig="FOSOI";

/*local*/ function $tg_get_tabs_attribute(/*gdx*/ tabs, /*string*/ name, /*integer*/ nFrames) {
    if (equal(name,`POSN`)) {
        return $subse($subse($ctrl_xtra,tabs),$CXTAB_SEL);
    } else if (equal(name,`SHOWCLOSE`)) {
        return $subse($subse($ctrl_xtra,tabs),$CXTAB_CLOSE);
    }
    $tg_bad_attr(tabs,name,nFrames+1);
} $tg_get_tabs_attribute.$sig="FOSI";

/*global*/ function gTabs(/*object*/ tabitems, /*rtn*/ tabchanged=NULL, /*sequence*/ attributes="", args=["sequence"]) {
    [,tabchanged,attributes,args] = $paranormalise_raa(tabchanged,attributes,args);
    let /*gdx*/ tabs = gCanvas($tg_tabs_redraw,`SIZE=0x24,EXPAND=HORIZONTAL`,{},2);
    $ctrl_types = $repe($ctrl_types,tabs,$TABS);
    $ctrl_set_attr = $repe($ctrl_set_attr,$TABS,$tg_set_tabs_attribute);
    $ctrl_get_attr = $repe($ctrl_get_attr,$TABS,$tg_get_tabs_attribute);
    let /*object*/ tabs_attr = repeat(0,$CXTAB_LEN);
    tabs_attr = $repe(tabs_attr,$CXTAB_ITEMS,tabitems);
    tabs_attr = $repe(tabs_attr,$CXTAB_SEL,1);
    tabs_attr = $repe(tabs_attr,$CXTAB_1ST,1);
    tabs_attr = $repe(tabs_attr,$CXTAB_BUMP,true);
    $ctrl_xtra = $repe($ctrl_xtra,tabs,tabs_attr);
    tabs_attr = 0;
    $tg_register_handler($TABS,`TABITEMS`,["sequence",`FO`,`F`]);
    $tg_register_handler($TABS,`TABCHANGED`,["sequence",`POII`,`PII`]);
//  $tg_register_handler($TABS,`TABCLICK`,{`POPIIII`})
    gSetAttribute(tabs,`BGCLR`,$TAB_BGCLR);
    gSetHandler(tabs,["sequence",`MOUSEMOVE`,`MOUSELEAVE`],$tg_tabs_mousemoveleave);
    gSetHandler(tabs,`CLICK`,$tg_tabs_click);
    gSetHandler(tabs,`KEY`,$tg_tabs_key_handler);
    if (integer(tabitems)) {
        gSetHandler(tabs,`TABITEMS`,tabitems); // (for the sig check only)
    }
    if (tabchanged) {
        gSetHandler(tabs,`TABCHANGED`,tabchanged);
    }
    if (length(attributes)) {
        gSetAttributes(tabs,attributes,args,2);
    }
    return tabs;
} gTabs.$sig="FOIPP,1";
