    tree_attr = 0;
    gSetAttribute(tree,`DATA`,nodes);
    $tg_register_handler($TREE,`CHECKED`,["sequence",`POPI`,`PPI`]);
    $tg_register_handler($TREE,`DATA`,["sequence",`FOP`,`FP`]);
    $tg_register_handler($TREE,`SELECTED`,["sequence",`POPI`,`PPI`]);
    gSetHandler(tree,`CLICK`,$tg_tree_click);
    gSetHandler(tree,`MOUSEMOVE`,$tg_tree_hover);
