        let /*integer*/ w = max($subse($subse($ctrl_size,id),$SZ_USER_W),$subse($subse($ctrl_size,id),$SZ_NORMAL_W)), 
                        h = max($subse($subse($ctrl_size,id),$SZ_USER_H),$subse($subse($ctrl_size,id),$SZ_NORMAL_H));
        $tg_lm_accumulate_and_disperse_user_sizes(id,w-dw,h-dh);
        if (equal(x,$TG_CURRENT)) { x = TG_CENTER; }
        if (equal(y,$TG_CURRENT)) { y = TG_CENTER; }
