/*local*/ function $tg_unit_test(/*gdx*/ dlg, /*string*/ what, /*integer*/ w, h, /*gdx*/ id1=NULL, id2=NULL) {
    gShow(dlg);
    if (equal(what,`DIALOG_SIZE`)) {
        let /*integer*/ left, top, width, height;
                crash(`JS`);
        assert(width===w);
        assert(height===h);
    } else if (equal(what,`CANVAS_SIZE`)) {
        assert(equal($subse($subse($ctrl_size,id1),$SZ_W),w));
        assert(equal($subse($subse($ctrl_size,id2),$SZ_W),w));
        assert(equal($subse($subse($ctrl_size,id1),$SZ_H),h));
        assert(equal($subse($subse($ctrl_size,id2),$SZ_H),h));
    } else {
        crash("9/0"); // unknown "what"
    }
    $gHide(dlg);
        // do nothing...
    $clear_tables();
} $tg_unit_test.$sig="POSIIOO,1";

/*local*/ function $tg_unit_tests() {
    // not invoked when $run_unit_tests is false or main file not in demo\theGUI\.
    $nodump = true; // (also avoid gtk_main_quit)
    // both same, from gCanvasX.exw:
    let /*gdx*/ cnv, dlg;
    cnv = gCanvas();
    dlg = gDialog(cnv,`edge`,`SIZE = 302x332`);
    $tg_unit_test(dlg,`DIALOG_SIZE`,302,332);
    cnv = gCanvas(`SIZE = 300x300`);
    dlg = gDialog(cnv,`edge`);
    $tg_unit_test(dlg,`DIALOG_SIZE`,302,332);
    let /*gdx*/ cv1, cv2, box;
    cv1 = gCanvas();
    cv2 = gCanvas();
    box = gHbox(["sequence",cv1,cv2]);
    dlg = gDialog(box,`edge`,`SIZE = 212x142`);
    gSetAttribute(box,`GAP`,`10`);
    gSetAttribute(box,`MARGIN`,`10`);
    $tg_unit_test(dlg,`CANVAS_SIZE`,90,90,cv1,cv2);
    cv1 = gCanvas();
    cv2 = gCanvas();
    box = gHbox(["sequence",cv1,cv2]);
    dlg = gDialog(box,`edge`);
    gSetAttributes(["sequence",cv1,cv2],`SIZE=90x90,EXPAND=NO`);
    gSetAttribute(box,`GAP`,`10`);
    gSetAttribute(box,`MARGIN`,`10`);
    $tg_unit_test(dlg,`CANVAS_SIZE`,90,90,cv1,cv2);
    cv1 = gCanvas();
    cv2 = gCanvas();
    box = gHbox(["sequence",cv1,cv2]);
    dlg = gDialog(box,`edge`);
    gSetAttributes(["sequence",cv1,cv2],`SIZE=90x90,EXPAND=NO`);
    gSetAttribute(box,`GAP`,`10`);
    gSetAttribute(box,`MARGIN`,`10`);
    $tg_unit_test(dlg,`DIALOG_SIZE`,212,142);
    $nodump = false;
} $tg_unit_tests.$sig="P";
